window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q12"]=window.__LIBQ["the-gioi-hoan-my"]["q12"]||{};window.__LIBQ["the-gioi-hoan-my"]["q12"]["cotTruyen"]=[{"chuong":1101,"tieuDe":"Toàn Diện Khai Chiến","tomTat":"Tô Lan và Trần Nặc lo Thạch Hạo cố ý gây chuyện, nhưng vẫn đứng xa quan sát khi hắn tìm đến động phủ của Thích Lâm để khiêu chiến. Thạch Hạo dùng lôi đình diễn hóa thành những quả cầu tím như một tinh vực thu nhỏ, đánh trọng thương Thích Lâm dù nàng đã vận dụng tiên khí. Sau chiến thắng, hắn chuyển sạch đồ trong động phủ, luộc vật cưỡi của nàng và lấy đi bốn bình Hoàng Huyết. Hắn tiếp tục mượn danh Vương Hi để hướng xung đột sang Yêu Nguyệt, đồng thời tuyên bố đang chuẩn bị cho cuộc chiến toàn diện. Thạch Hạo lần lượt quan sát tịnh thổ của Yêu Nguyệt, Lục Đà và Phong Hành Thiên nhưng không khiêu chiến họ. Khi biết Nguyên Phong là hậu nhân của Nguyên Thanh và đã tu thành hai đạo tiên khí, hắn lập tức đến đạo thổ của người này. Chương kết thúc lúc Nguyên Phong xuất hiện và nhìn chằm chằm Thạch Hạo với khí thế sắc bén như lợi kiếm ra khỏi vỏ."},{"chuong":1102,"tieuDe":"Khởi Hành","tomTat":"Thạch Hạo tìm tới chỗ Nguyên Phong nhưng không khiêu chiến ngay trong Thiên Thần Thư Viện, bởi hắn muốn chờ tới tiên gia chiến trường mới săn giết đối phương và thu một phần lợi tức từ Nguyên Thanh. Nguyên Phong chủ động đòi dùng Hoàng Huyết cược chiến dù chưa có vật cược, sau đó viện cớ bảo vệ danh dự đệ tử chính thức để cưỡng ép giao thủ bằng cốt văn và hai đạo tiên khí. Thạch Hạo cố ý thu liễm thực lực, rời trận mà không phân thắng bại; Nguyên Phong cũng được một số người cho mượn Hoàng Huyết để chuẩn bị tái chiến. Kế hoạch này tạm gác khi Thiên Thần Thư Viện thông báo mở đường tiến vào tiên gia chiến trường theo nguyên tắc tự nguyện. Vương Hi, Lục Đà, Phong Hành Thiên, Yêu Nguyệt, Huyền Côn cùng đông đảo đệ tử quyết định lên đường vì những cơ duyên và di vật cổ đại được truyền tụng tại chiến trường. Hoàng kim cự thuyền chở đoàn người rời thư viện, còn Thạch Hạo nhận ra Ma Nữ, Tào Vũ Sinh, Trường Cung Diễn, Tiểu Thỏ Tử và Thanh Y nhưng không hội hợp để tránh liên lụy họ vào sát cục sắp tới."},{"chuong":1103,"tieuDe":"Tiên Gia Chiến Trường","tomTat":"Hoàng kim cự thuyền đưa đoàn Thiên Thần thư viện vượt qua cổ địa đầy Tiên Đạo tàn trận và tới một trong bốn đại tế đàn thời xưa. Các trưởng lão gần như cạn sức khi hiến tế bảo huyết, định tọa độ và kích hoạt một phần tế đàn để mở đường hầm không gian vượt qua hàng trăm nghìn tinh hệ. Điểm đến là Tiên gia chiến trường, một hòn đảo khổng lồ tựa đại lục treo giữa vũ trụ, có lực bài xích khiến chiến thuyền suýt nóng chảy. Tại vùng đất đỏ nâu ở rìa chiến trường, đoàn người gặp quái vật lông đỏ do Tiên Đạo sát khí ngưng tụ và được cảnh báo rằng nơi đây còn có những sinh vật nguy hiểm hơn. Các trưởng lão chỉ phát cốt phù bảo mệnh cho đệ tử chính thức, khiến Thạch Hạo không được nhận dù Vương Hi đã thử xin thêm một tấm. Nguyên Phong nhân cơ hội chế giễu và đe dọa Thạch Hạo, nhưng hắn vẫn bình tĩnh chuẩn bị săn giết đối thủ. Cuộc thí luyện lập tức bộc lộ mức độ tàn khốc khi một người theo đuổi kỳ tài bị quái vật lông đỏ ăn sạch đầu lâu lẫn Nguyên Thần ngay gần nơi hạ thuyền."},{"chuong":1104,"tieuDe":"Đỏ Mặt","tomTat":"Sau cái chết xảy ra lúc hành trình vừa bắt đầu, các đệ tử Thiên Thần Thư Viện tiến sâu vào chiến trường cổ trong đội hình cảnh giác. Yêu Nguyệt trêu chọc quan hệ giữa Thạch Hạo và Vương Hi, nhưng Vương Hi chủ động rời đi để tránh một cuộc quyết đấu có thể giúp các đối thủ khác hưởng lợi. Một thú triều do hung sát khí pha lẫn khí tức Tiên Đạo hóa thành bất ngờ tràn tới, buộc toàn bộ đoàn người phải phản công. Lục Đà xông lên mở đường, còn Thạch Hạo tách khỏi Vương Hi để tìm và giải cứu nhóm tu sĩ ba ngàn đạo châu. Khi Nguyên Phong cùng thuộc hạ tiếp tục khinh miệt nhóm người này, Thạch Hạo tung một quyền đánh nổ toàn bộ những người theo đuổi hắn. Chương kết thúc khi Thạch Hạo gọi Nguyên Phong tới nhận chết và lao thẳng về phía đối phương."},{"chuong":1105,"tieuDe":"Đánh Giết Nguyên Phong","tomTat":"Thạch Hạo truy sát Nguyên Phong và dùng một quyền đánh nát chiến mâu Hoàng Kim, khiến đối phương thổ huyết rồi bỏ chạy. Từ sức mạnh, ánh mắt và mối thù do Nguyên Thanh gây ra, Nguyên Phong dần nhận ra người truy sát mình chính là Hoang. Hắn tiếp tục dùng mảnh mai rùa Chí Tôn hộ thân nhưng Thạch Hạo lấy Đại La Tiên Kiếm thai đánh bật và đâm thủng bảo cụ này. Trước mặt những tu sĩ đang đuổi tới, Thạch Hạo để Nguyên Phong nhìn rõ chân dung thật rồi trở lại diện mạo người theo đuổi Vương Hi nhằm tiếp tục che giấu thân phận. Dù Nguyên Phong cầu xin và viện dẫn tổ phụ, Thạch Hạo vẫn tung quyền đánh nổ thân thể hắn. Khi phát hiện Nguyên Thần đối phương ẩn trong cốt phù bảo mệnh và đang hấp thu huyết tinh để tái tạo thân thể, Thạch Hạo bóp nát cốt phù, khiến Nguyên Phong hoàn toàn tử vong."},{"chuong":1106,"tieuDe":"Chí Tôn Trẻ Tuổi Chiến","tomTat":"Sau khi đánh chết Nguyên Phong, Thạch Hạo che giấu chân thân rồi dùng máu đối phương viết huyết thư tố cáo Nguyên Thanh tư lợi đưa cháu vào Thiên Thần Thư Viện. Hắn vượt qua đàn thú do sát khí biến thành và trở lại bên Vương Hi, đúng lúc Vương Hi đối đầu Lục Đà còn Yêu Nguyệt giao chiến với Huyền Côn. Lục Đà bỏ qua Vương Hi để nhắm thẳng vào Thạch Hạo, nhưng bị nàng dùng pháp ấn bảo bình ngăn cản. Sáu người theo đuổi Lục Đà tiếp tục vây công bằng kỳ trận, song Thạch Hạo vận dụng Súc địa thành thốn phá thế hợp trận và đánh chết người chủ công đã tu thành một đạo tiên khí. Lục Đà dùng đạo âm định giết hắn nhưng Vương Hi kịp thời trung hòa sát chiêu. Cuối cùng, Yêu Nguyệt và Huyền Côn bất ngờ cùng lao vào chiến trường của Vương Hi và Lục Đà, khiến Thạch Hạo nhận ra ba trong bốn chí tôn trẻ tuổi có thể đã bí mật liên thủ để loại bỏ người còn lại."},{"chuong":1107,"tieuDe":"Phục Kích","tomTat":"Thạch Hạo bí mật quan sát khi Vương Hi, Yêu Nguyệt và Huyền Côn hợp sức vây đánh Lục Đà, khiến hắn trọng thương và phải thiêu đốt tinh huyết để đào thoát. Ngay sau đó, Yêu Nguyệt cùng Huyền Côn quay sang phục kích Vương Hi, nhưng nàng vẫn phá được vòng vây và mang Thạch Hạo rời khỏi chiến trường. Vương Hi uống thần đan chữa thương dưới sự hộ pháp của Thạch Hạo rồi tìm đến Lục Đà, thuyết phục đối thủ vừa bị mình vây đánh tạm thời hợp tác để tự bảo toàn. Hai người phản phục kích thành công, đánh Huyền Côn trọng thương và tiếp tục truy kích Yêu Nguyệt. Huyền Côn vì đề phòng Yêu Nguyệt nên quả đoán rời đi, còn Yêu Nguyệt cũng bị đánh đến chảy máu trước khi rút lui. Khi cả bốn chí tôn trẻ tuổi đều mang thương tích, Thạch Hạo bắt đầu cân nhắc tận dụng thời cơ nhập cuộc bằng đóa đại đạo chi hoa mới tu thành."},{"chuong":1108,"tieuDe":"Không Đầu","tomTat":"Sau trận hỗn chiến, Yêu Nguyệt, Lục Đà và các chí tôn trẻ tuổi lần lượt rút lui vì đều chịu thương tổn bản nguyên. Khi Thạch Hạo định truy sát Lục Đà, một sinh linh không đầu mang giáp trụ cổ xưa bất ngờ xuất hiện, tàn phá núi non và diệt sạch hung vật quanh đó trước khi tiến về chiến thuyền hoàng kim của Thiên Thần Thư Viện. Vương Hi giải thích đây là cổ nhân chết tại tiên gia chiến trường nhưng thân thể còn sức sống, được mai táng ở nơi có thần dược rồi thông linh sau thời gian dài. Do ẩn dưới ngọn núi bị cổ thi giẫm vỡ, thương thế của Vương Hi trở nên nghiêm trọng hơn. Nàng cảnh báo Thạch Hạo rằng người đạt tam hoa tụ đỉnh mạnh hơn hẳn người mới kết hai đóa đạo hoa, đồng thời cho biết đệ nhị cao thủ của thư viện đang mang Cửu Hoàng lô bảo vệ chiến thuyền. Hai người dùng chiến xa bảy màu rời vùng thú triều rồi suy đoán nơi mai táng sinh linh không đầu có thể chứa thần dược hoặc một tiên gia động phủ. Vương Hi ở lại chữa thương, còn Thạch Hạo một mình lên đường tìm bí địa và dò tung tích Yêu Nguyệt, Lục Đà cùng Huyền Côn."},{"chuong":1109,"tieuDe":"Phong Tộc Hiện","tomTat":"Thạch Hạo chạy khắp vùng đất đỏ nâu để tìm thần dược, đạo thư, Tiên khí và tiên gia động phủ nhưng chưa có thu hoạch. Sau khi phát hiện thuộc hạ của một chí tôn trẻ tuổi dùng cốt kính dò xét lòng đất và bàn chuyện săn người tu thành ba đạo tiên khí, hắn quay lại kiểm tra an nguy của Vương Hi. Vương Hi đã dùng bí bảo gia tộc thu liễm khí tức để tránh Phong Hành Thiên, rồi tháo Kim Cương trác khỏi Thạch Hạo để hắn không bị nhận diện. Thạch Hạo tiếp tục lên đường và chứng kiến Phong Hành Thiên dùng hắc ám thiên công truy sát Huyền Côn đang trọng thương nhưng chưa thể giết được đối phương. Hắn sau đó phát hiện Chân Cổ, Đằng Nhất cùng nhiều tu sĩ ba ngàn châu bị người Phong tộc cưỡng ép tìm kiếm cơ duyên và công khai khinh miệt. Qua lời bàn luận của họ, Thạch Hạo biết một lão tổ Phong tộc từng bất hòa với vị vương Thạch tộc tại Biên Hoang, hé lộ căn nguyên sâu xa của việc Phong tộc muốn áp chế Hoang. Tức giận trước sự sỉ nhục, hắn ngưng tụ hoàng kim chiến đao bằng sấm sét và chém ngang lưng nhiều người của phe Phong tộc. Động tĩnh này lập tức khiến Phong Hành Thiên ở xa chú ý và phóng khí thế khủng bố bao phủ tới."},{"chuong":1110,"tieuDe":"Va Chạm Mạnh","tomTat":"Thạch Hạo dùng hoàng kim chiến đao, chỉ lực và quyền ấn quét sạch lực lượng đi theo Phong Hành Thiên, đồng thời phá hủy những bảo mệnh cốt phù định thu tinh huyết đưa chủ nhân bỏ chạy. Nhờ Thất Thập Nhị Biến tái tạo xương cốt và huyết nhục, hắn không bị tu sĩ ba ngàn châu nhận ra, ngay cả Thiên Nhãn thông cũng không thể nhìn thấu. Thạch Hạo xác định Phong tộc mới là chủ mưu áp chế và đẩy mình tới Thái Sơ cổ quáng, còn Nguyên Thanh chỉ là đồng lõa. Trong lúc Phong Hành Thiên giao chiến với Huyền Côn, Yêu Nguyệt mang thương tích tới cứu viện và cùng đồng minh đối kháng Thập tự thần đạo cùng hắc ám thiên công. Dư ba cuộc quyết đấu phá nát chiến trường tiên gia, để lộ một cung điện rộng lớn trong vực sâu và khiến cây thần dược ẩn tại đó hiện thân rồi trốn vào bên trong. Thạch Hạo kết sáu loại pháp ấn, thi triển Lục Đạo Luân Hồi và phối hợp với Yêu Nguyệt, Huyền Côn đánh tan thế hắc ám thiên công, khiến Phong Hành Thiên thổ huyết bay ngang. Dù bị trọng thương, Phong Hành Thiên vẫn cưỡng ép thân thể lao về cung điện dưới lòng đất để tranh đoạt cơ duyên."},{"chuong":1111,"tieuDe":"Vực Sâu Ác Chiến","tomTat":"Thạch Hạo kết ấn thi triển Lục Đạo Luân Hồi Thiên Công, dung hợp sáu loại bảo thuật thành vô thượng phù văn và đánh Phong Hành Thiên ho ra máu. Yêu Nguyệt nhận ra lai lịch thiên công này và đặc biệt chú ý đến người thi triển. Phong Hành Thiên lui về phía cung điện dưới lòng đất, phủ hắc ám lên vực sâu và đe dọa giết những người muốn tranh Tiên duyên, nhưng Thạch Hạo vẫn truy kích rồi dùng cốt văn lôi điện phá mở bóng tối. Hai người tiếp tục so đấu bằng thể thuật, hắc ám ma quyền và cổ thiên công, khiến địa tầng cùng hư không chung quanh tan vỡ trong khi các cung điện vẫn nguyên vẹn. Thể phách của Thạch Hạo khiến Phong Hành Thiên kinh ngạc vì hắn không thể giành ưu thế dù từng được Hoàng Huyết tôi luyện. Yêu Nguyệt và Huyền Côn sau đó cùng nhập trận, ép Phong Hành Thiên tiếp tục thổ huyết và rút vào cung điện. Dao động từ trận chiến lan khắp các phương, thu hút nhiều người tới vực sâu và khiến họ kinh ngạc trước thiếu niên xa lạ có thể giao chiến trực diện với thiên kiêu Phong tộc."},{"chuong":1112,"tieuDe":"Cung Điện Dưới Lòng Đất","tomTat":"Phong Hành Thiên dẫn đầu xông vào cung điện dưới vực sâu, theo sau là Thạch Hạo, Yêu Nguyệt và Huyền Côn; cả nhóm phát hiện bên trong kiến trúc ngầm là một Tiểu Thiên Thế Giới xanh tốt. Phong Hành Thiên tập kích rồi thách Thạch Hạo đơn đấu, nhưng Yêu Nguyệt và Huyền Côn nhanh chóng phá lời tuyên bố đứng ngoài để cùng tấn công hắn. Hắn kết hợp hắc ám thiên công với bản nguyên lực Phong tộc, biến khu vực thành trường săn tối tăm và liên tiếp tập kích ba đối thủ. Một số đệ tử chính thức tiến vào tìm truyền thừa bị dư ba đại chiến nghiền nát thân thể, chỉ giữ được tính mạng nhờ cốt phù hấp thu tinh huyết và đưa họ rời đi. Thạch Hạo tạo duy nhất động thiên để cầm cố khu vực, sau đó dùng Lục Đạo Luân Hồi ấn diễn hóa sáu hố đen hút sạch cuồng phong rồi áp sát đánh Phong Hành Thiên thổ huyết. Bốn cao thủ vừa giao chiến vừa tiến sâu, bắt gặp một con thần dược độn xuống đất và cuối cùng tìm thấy chiếc ao bốc lên linh khí cùng tiên khí. Trước dấu hiệu về Tiên duyên và bí mật của sinh linh không đầu, Thạch Hạo, Yêu Nguyệt và Huyền Côn thống nhất ưu tiên vây giết Phong Hành Thiên."},{"chuong":1113,"tieuDe":"Điệp","tomTat":"Thạch Hạo, Yêu Nguyệt, Huyền Côn và Phong Hành Thiên cùng lao tới cổ trì vì tưởng bên trong cất giấu một Tiên khí vô giá, khiến liên minh tạm thời lập tức tan vỡ. Huyền Côn ra tay ngăn Thạch Hạo nhưng bị lực lượng lục đạo luân hồi đánh tới ho ra máu, trong khi Yêu Nguyệt giao chiến dữ dội với Phong Hành Thiên. Phù văn của bốn cao thủ hòa vào nhau rồi phát nổ, làm vòm trời phía trên vực sâu sụp nứt. Khi cả bốn định chộp lấy vật trong ao, khí tức nguy hiểm buộc họ đồng loạt rút lui và nhận ra thứ bên dưới có thể là một sinh vật. Hoàng Điệp trong cốt đỉnh của Thạch Hạo thức tỉnh khi cảm nhận khí tức ấy, còn Yêu Nguyệt nhìn ra hình dạng một con bướm. Sương mù tan bớt để lộ di hài cổ điệp mục nát, được nhận định từng là một trường sinh giả chết trận từ thời Tiên cổ và vẫn đang bị bí lực của kẻ địch ăn mòn. Huyền Côn, Phong Hành Thiên và Yêu Nguyệt đều nảy ý định chiếm lấy di hài cùng những đạo thư hoặc binh khí có thể còn ẩn bên trong."},{"chuong":1114,"tieuDe":"Phong Hầu","tomTat":"Hoàng điệp bất ngờ sống lại khiến Thạch Hạo kinh hỉ, còn Huyền Côn vì bị thương nặng nên đề nghị cùng Thạch Hạo và Yêu Nguyệt chia đều tiên gia di bảo. Bị loại khỏi thỏa thuận, Phong Hành Thiên ra tay trước bằng Hắc Ám chi lực và Cương Phong nhưng bị ba người đồng thời vận dụng cổ thiên công đánh trọng thương. Thạch Hạo thi triển Lục Đạo Luân Hồi với sáu lỗ đen biến hóa, góp phần áp đảo đối thủ. Đúng lúc ấy, Phong Chiêu xuất hiện và được Phong Hành Thiên gọi là Lục thúc, qua đó lộ thân phận Phong Hầu có địa vị quan trọng trong Phong tộc. Cường giả này từng trải qua đại Niết Bàn ở Thiên Thần cảnh, đã bí mật giả dạng tiểu tu sĩ để theo chiến thuyền Thiên Thần thư viện tới đây. Hắn cũng chính là người từng tìm Nguyên Thanh để sắp đặt việc đối phó Thạch Hạo theo ý lão tổ Phong tộc. Phong Chiêu muốn bắt Thạch Hạo, Yêu Nguyệt và Huyền Côn nhằm nghiên cứu thiên công, cướp đạo quả và tróc bong thể xác của những người tu ra ba đạo tiên khí. Vì căm ghét người biết Lục Đạo Luân Hồi Thiên Công, hắn nhắm Thạch Hạo trước tiên, buộc Thạch Hạo chuẩn bị dùng Vạn Linh đồ và Lôi Đế áo giáp tự vệ."},{"chuong":1115,"tieuDe":"Trảm Phong","tomTat":"Phong Chiêu bộc lộ ý định chiếm dụng thân thể Thạch Hạo và các thiên tài khác để tạo ra cao thủ bảo vệ bản thân cùng một số tộc nhân, thậm chí còn định xóa ký ức Phong Hành Thiên nhằm thủ tiêu dấu vết. Yêu Nguyệt và Huyền Côn phản đối, cảnh báo rằng sự biến mất của những người tu thành ba đạo tiên khí sẽ gây đại loạn. Trong lúc đối thoại, Thạch Hạo âm thầm trao đổi với Hoàng Điệp và nhận được tin quan trọng, từ đó bình tĩnh dẫn dụ Phong Chiêu ra tay. Cổ điệp mục nát bất ngờ bay khỏi linh trì, đánh nổ bàn tay phải của Phong Chiêu rồi dùng Tiên Đạo lực lượng tiêu diệt cả thân thể lẫn nguyên thần của hắn. Sau khi trảm sát Phong Chiêu, cổ điệp trở về ao ngủ đông, còn Hoàng Điệp bí mật bay vào linh trì để tiếp cận nó. Thạch Hạo lập tức chuyển sang tập kích Phong Hành Thiên và dùng Lục Đạo Luân Hồi Thiên Công đánh xuyên lồng ngực đối thủ."},{"chuong":1116,"tieuDe":"Cốt Thi","tomTat":"Phong Hành Thiên bị Lục Đạo Luân Hồi Thiên Công đánh tan thân thể, còn cốt phù mang theo sinh cơ của hắn cũng bị Thạch Hạo, Yêu Nguyệt và Huyền Côn hợp sức nghiền nát, khiến hắn hoàn toàn mất khả năng phục sinh. Ba người thống nhất che giấu cái chết của Phong Hầu để tránh bị điều tra, dù Yêu Nguyệt và Huyền Côn càng thêm kiêng dè Thạch Hạo. Sau khi cổ điệp mục nát tan rã, Hoàng Điệp hấp thu Tiên Đạo khí tức, niêm phong chân huyết cùng tộc và chuẩn bị ngủ say để tiến hóa. Thạch Hạo tiếp tục khảo sát các cổ điện đã bị càn quét, từ đó suy ngẫm rằng hậu thế cần khai sáng một hệ thống tu luyện hoàn toàn mới mới có hy vọng chiến thắng kẻ địch. Tại trung ương cung điện, ba người truy bắt Hỏa diệp lan nhưng thần dược liên tục hòa vào lòng đất, trong khi khí tức của sinh linh không đầu đang tiến gần. Cuối cùng, Thạch Hạo dịch chuyển tế đàn nứt vỡ và phát hiện một chìa khóa bằng bạch cốt giấu bên trong, dù Võ đạo Thiên nhãn trước đó không nhìn ra dấu vết."},{"chuong":1117,"tieuDe":"Gió Nổi Lên","tomTat":"Thạch Hạo tình cờ tìm thấy một cốt thược trắng như ngọc trong khe nứt của tế đàn tím nhạt, nhận ra vật này không thể bị Võ đạo Thiên nhãn nhìn thấu và có chất liệu tương tự Vạn Linh Đồ nên bí mật thu giữ. Sau khi phá tế đàn mà không tìm thêm được gì, hắn phối hợp với Yêu Nguyệt và Huyền Côn vây bắt Hỏa diệp lan, nhưng thần dược độn thổ thoát đi nhờ hệ thống cổ trận phức tạp dưới lòng đất. Sinh linh không đầu bất ngờ trở về, truy kích Thạch Hạo xuyên qua hư không và buộc hắn phải dùng Phá giới phù cùng Vạn Linh Đồ mới thoát chết. Sinh linh cổ tiếp tục áp chế một nhân vật đỉnh cấp của Thiên Thần Thư Viện, khiến những người quanh vực sâu kinh hoàng bỏ chạy. Tin hồn đăng của Phong Hành Thiên đã tắt xác nhận thiên tài này tử vong, làm dấy lên lời đồn về hung thủ và nguy cơ Phong tộc trả thù. Thạch Hạo sau đó gặp Vương Hi vừa thoát khỏi một cuộc truy sát, xác nhận mình tận mắt chứng kiến cái chết của Phong Hành Thiên và tiết lộ từng suýt tự tay giết đối phương. Ở nơi cách đó hàng nghìn dặm, tế đàn yêu tà trên ngọn núi đen tự mở một đường nối giữa huyết quang, để lộ tiếng người hô ngựa hí từ phía bên kia. Một cơn gió lớn lập tức quét khắp đại địa, báo hiệu biến động mới sắp lan rộng."},{"chuong":1118,"tieuDe":"Càn Khôn Đại","tomTat":"Sau trận chiến, Thạch Hạo đỡ Vương Hi vào chiến xa, còn nàng dù trọng thương vẫn dùng ba đạo tiên khí điều động Kim Cương trác khóa trên đầu hắn. Thạch Hạo cố ý không tránh để món pháp bảo trở thành lớp ngụy trang cho việc hắn đã giết Phong Hành Thiên, đồng thời trêu chọc và tự tâng bốc khi Vương Hi dò hỏi về hung thủ. Dị tượng bầu trời máu, tia chớp đen và lốc xoáy lông đỏ dẫn các đệ tử Thiên Thần Thư Viện tới một ngọn núi đen, nơi cổ tế đàn đang mở đường nối mang quy tắc đối lập với Cửu Thiên Thập Địa. Vương Hi uống thần đan màu vàng để giảm thương thế nhưng đại đạo thương vẫn chưa khỏi hẳn. Từ đường nối, một chiếc túi tỏa hỗn độn khí và ngũ sắc thần hà lao ra, phóng luồng gió đủ sức diệt Thiên Thần và giáo chủ nên bị quy tắc cùng xích thần trật tự của thiên địa áp chế. Vương Hi nhận ra Càn Khôn đại, còn Lục Đà xác nhận đây là phiên bản nguyên thủy mạnh nhất của chí bảo. Khi biết nó có thể là pháp khí Tiên Vương từng thất lạc phía bên kia Biên Hoang và rơi vào tay địch, tất cả những người hiện diện đều tái mặt trước nguy cơ sắp tới."},{"chuong":1119,"tieuDe":"Hàn Ý","tomTat":"Càn Khôn đại thất lạc ở phía bên kia Biên Hoang tái hiện, mở một vùng không gian bao phủ ngọn núi đen và đối kháng quy tắc Cửu Thiên Thập Địa. Lục Đà nhận ra chí bảo đang gánh ý chí của sinh linh dị giới để mở đường vượt giới, trong khi những người chứng kiến kinh hãi vì binh khí Tiên Vương từng thuộc bản giới đã bị đối phương luyện hóa. Các trưởng lão Thiên Thần Thư Viện nhanh chóng tới hiện trường và lo ngại đại họa được dự báo đã bắt đầu. Khi đường nối vừa ổn định, một sinh linh thế giới bên kia bất ngờ vượt qua bằng cách mượn bộ xương của một nữ cường giả thay vì sử dụng bản thể. Một trưởng lão nhận ra hài cốt ấy thuộc về nữ tổ tiên trong cổ tộc Trường Sinh của mình nên nổi giận muốn giao chiến. Kẻ vượt giới còn tiết lộ phía bên kia đang giữ nhiều di cốt thiên tài mạnh hơn và nhắc tới những cường giả từng tự phong trong thạch thất nhưng sau đó chỉ để lại thân xác không còn Nguyên Thần."},{"chuong":1120,"tieuDe":"Đối Mặt","tomTat":"Các kỳ tài trẻ tuổi tiến qua màn sáng ở ngọn núi đen để tham chiến, trong khi Thạch Hạo khuyên người tu vi thấp không nên liều mạng và thẳng thắn tuyên bố sẽ chạy nếu gặp cường giả cấp giáo chủ. Thập Giới Đồ phối hợp với Càn Khôn đại đưa đoàn người vào một vùng thiên địa rộng lớn, tràn đầy sinh cơ và được ngăn cách với đường lui bằng giới bích hỗn độn. Sau khi Thạch Hạo thử công kích ranh giới nhưng không thể phá vỡ, cả đoàn dùng một tòa cổ Truyền Tống trận để tới chiến trường núi đá đỏ. Tại đó, họ trực tiếp đối mặt với một nhóm kỳ tài trẻ tuổi của thế giới bờ bên kia, trong đó nhiều người mang Tiên Đạo khí và có khí huyết vô cùng mạnh mẽ. Thạch Hạo bí mật nêu suy đoán rằng hai phe vốn đồng loại, nhưng đối phương khinh miệt phủ nhận và cáo buộc Cửu Thiên Thập Địa đã bị ăn mòn, khiến nhận thức của đoàn người dao động trong thoáng chốc. Một sinh linh bí ẩn còn nhận ra dấu vết của kẻ từng trốn khỏi thế giới phía họ, sau đó thách Thạch Hạo giao chiến để tìm hiểu chân tướng. Cảm giác nguy hiểm từ đối thủ khiến Thạch Hạo nghi ngờ kẻ này có thể thực sự đến từ thế giới của kẻ địch."},{"chuong":1121,"tieuDe":"Hỗn Chiến","tomTat":"Một sinh linh ẩn trong bóng tối công khai nhục mạ Cửu Thiên Thập Địa, rồi dùng kiếm khí vô hình suýt chém đôi một đệ tử Thiên Thần Thư Viện; Thập Quan Vương kịp cản bớt uy lực nên người này còn sống. Trong lúc bí mật đối đáp với Thạch Hạo, kẻ địch tuyên bố tổ tiên từng trực tiếp tham chiến thời Tiên cổ vẫn còn tồn tại, khiến các kỳ tài Cửu Thiên Thập Địa chấn động. Hai phe sau đó đồng loạt xông lên, mở màn cuộc hỗn chiến dữ dội trong không gian do Thập Giới Đồ và Càn Khôn đại xây dựng. Nữ tử tóc nâu có ba đạo tiên khí đối đầu Lục Đà, còn nam tử mặc giáp vàng ròng nhắm tới Yêu Nguyệt và bị nàng dùng quyền ấn cùng ánh trăng phản kích. Thiếu niên áo bào trắng tấn công Vương Hi khi nàng đang trọng thương, buộc nàng thi triển Trăm Ngày Mười Hoàng Niết Bàn Công để tạm thời khôi phục trạng thái đỉnh cao dù phải chịu tổn thương lớn về sau. Giữa chiến trường hỗn loạn, Thạch Hạo tập trung truy tìm sinh linh ẩn thân, cuối cùng cảm ứng được khí thế đối phương và đánh xuyên hư không để chính thức nghênh chiến."},{"chuong":1122,"tieuDe":"Hư Không Vương Thú","tomTat":"Thạch Hạo phá vỡ vùng hư không che giấu, buộc một hung thú khổng lồ có mười tám sừng lộ chân thân giữa vùng núi rừng nguyên thủy. Hắn nhận ra đối thủ là Hư Không Thú gần như đã tuyệt tích, còn sinh linh này tự nhận mang huyết mạch vương giả thuần chính từ thế giới bờ bên kia. Sau khi một quyền đánh hụt vì đối thủ biến mất trong hư không, Thạch Hạo dùng ba đạo tiên khí thúc đẩy Côn Bằng pháp, diễn hóa một trăm lẻ tám nghìn hoàng kim vũ kiếm công kích khắp mười phương. Hư Không Vương Thú tránh hoặc dời chuyển phần lớn đòn đánh, đồng thời dùng màn sáng từ mười tám chiếc sừng ngăn số vũ kiếm còn lại. Nó nhận ra Thạch Hạo mang truyền thừa Côn Bằng, khiến những tu sĩ Thiên Thần Thư Viện đang quan sát kinh động. Hư Không Vương Thú sau đó phát động Hư Không Đại Liệt Trảm, còn Thạch Hạo xông qua khe nứt để áp sát, mở ra cuộc giao chiến tốc độ cao giữa hai bên."},{"chuong":1123,"tieuDe":"Lục Đạo Quyết Đấu Cửu Chuyển","tomTat":"Hư Không Vương Thú dùng thần tắc không gian, không gian chi nhận và năng lượng từ mười tám chiếc sừng giao chiến với Thạch Hạo, trong khi Thạch Hạo đáp trả bằng duy nhất động thiên cùng Bảo thuật Lôi Đế. Không thể nhanh chóng trấn áp đối thủ, hung thú chuyển sang tàn sát những tu sĩ trẻ đang quan chiến, khiến Thạch Hạo phẫn nộ nhưng không kịp cứu họ. Thạch Hạo lập tức trả đũa bằng cành liễu, ba đạo tiên khí, Lôi Đế chiến y, Đại La Tiên Kiếm và 108.000 lông thần màu vàng, tiêu diệt nhóm sinh linh thuộc thế giới bờ bên kia. Hư Không Vương Thú đưa hắn tới cuối dãy núi và tiết lộ mục đích độc chiếm những bí mật, cơ duyên liên quan đến chuyến đi qua biên giới thế giới bên kia. Thạch Hạo hoàn thành sáu pháp ấn mở đầu rồi dung hợp thành Lục Đạo Luân Hồi, tạo sáu hố đen khắc chế thần thông không gian bản mệnh của đối thủ. Hư Không Vương Thú phải vận dụng Cửu Chuyển thiên công để thoát khỏi thế nguy, sau đó hai bên cùng bị thương và chuyển sang cận chiến. Cuối chương, Thạch Hạo bị mười tám luồng sáng giam giữ nhưng tiếp tục kết ấn, lần nữa vận dụng cổ thiên công khi trận đấu vẫn chưa phân thắng bại."},{"chuong":1124,"tieuDe":"Đổ Máu","tomTat":"Thạch Hạo dùng Lục Đạo Luân Hồi quyết chiến với Hư Không Thú, trong khi đối thủ dựa vào bản mệnh thần thông hư không, Hư Không Mất Hồn và Cửu Chuyển Thiên Công để phản kích. Hai môn cổ thiên công liên tục va chạm khiến cả hai trọng thương, gần cạn bản nguyên, đồng thời phá hủy núi non, sông và hồ trong khu vực chiến trường. Khi không thể tiếp tục vận dụng tuyệt học mạnh nhất, Thạch Hạo chuyển sang pháp môn Côn Bằng, dùng lực âm dương phá kiếm khí hư không rồi lao xuống phản công. Hư Không Thú dựng Càn Khôn lò lớn để định thân và luyện hóa hắn, nhưng Thạch Hạo kết ba đạo tiên khí thành Đại đạo chi hoa và phá nổ lò luyện. Sau đó, Thạch Hạo thi triển Pháp Tướng thiên địa và kích hoạt năng lực có được từ Kim Bồ quả để tạm thời vô hiệu hóa bí pháp của đối thủ. Hắn áp sát, cưỡi lên Hư Không Thú, giữ chặt sừng và liên tục đánh vào đầu nó."},{"chuong":1125,"tieuDe":"Tuế Nguyệt Vi Tôn","tomTat":"Thạch Hạo cưỡi trên lưng Hư Không Vương Thú, dùng phép thuật miễn dịch vô hiệu hóa bảo thuật của nó rồi vận chuyển Côn Bằng pháp đánh đối thủ đến sát cảnh tử vong. Trong lúc thần trí hỗn loạn, Hư Không Vương Thú nhận ra năng lực của hắn tương tự một hoàng tộc tại thế giới của nó và nhắc đến một tộc ở thế giới này từng sở hữu năng lực tương tự. Khi nó sắp bị giết, đạo phù giấu trong nguyên thần bất ngờ kích hoạt, đưa nó trốn qua hư không, tái sinh hoàn toàn thân thể rồi vỡ thành tro. Thạch Hạo dùng Đại La Tiên Kiếm thai truy đuổi và nuốt Phượng Hoàng chân huyết để nhanh chóng khôi phục nguyên khí. Trong lần quyết chiến tiếp theo, Hư Không Vương Thú dùng tám sợi hư không gông xiềng khóa hắn và chuẩn bị phát động không gian chi nhận. Thạch Hạo chuyển sang Luân Hồi do Chí tôn cốt sinh ra, dùng lực lượng thời gian khiến đối thủ như già đi một vạn năm và suy kiệt tức thì. Hắn bẻ gãy xiềng xích, thoát khỏi giam cầm rồi giẫm nát nửa thân Hư Không Vương Thú, nhưng cái chết của nó chưa được xác nhận khi chương kết thúc."},{"chuong":1126,"tieuDe":"Giẫm Nát","tomTat":"Hư Không Vương Thú dù đã mất nửa thân thể vẫn cự tuyệt cung cấp tình báo về thế giới bờ bên kia, khiến Thạch Hạo giẫm nát miệng nó rồi tìm cách cưỡng ép dò xét nguyên thần. Cấm chế tự hủy của tộc Hư Không Thú lập tức xuất hiện để bảo vệ chí cường bảo thuật, nhưng đối phương đốt tinh huyết chống lại nên phù văn chưa bạo phát hoàn toàn. Thạch Hạo lấy một đại đỉnh chứa thần tuyền, chặt xuống tảng thịt dài khoảng mười trượng và chuẩn bị đem nấu, buộc Hư Không Vương Thú thiêu hủy phần thân thể còn lại để niết bàn. Lôi kiếp, hư không bí lực và hư ảnh Cổ Tổ cùng xuất hiện, khiến sinh linh bỉ ngạn nhận ra dị tượng Hư Không Vương Thú còn người Thiên Thần thư viện lo ngại nó sẽ mạnh hơn sau khi tái sinh. Khi Thạch Hạo bị sức mạnh hư không ngăn cản, thân ảnh mơ hồ trong Đại đạo chi hoa trên đầu hắn mở mắt, làm hư ảnh Cổ Tổ cùng toàn bộ bí lực tan biến và khiến niết bàn thất bại. Thạch Hạo lập tức dùng Đại La Tiên Kiếm thai bổ đôi đầu lâu cùng nguyên thần đối phương, khiến Hư Không Vương Thú hình thần câu diệt. Sau đó, hắn thu đại đỉnh chứa phần thịt còn lại, trở về chiến trường và bình thản báo với Vương Hi rằng mình đã chặt chết Hư Không Vương Thú đang niết bàn."},{"chuong":1127,"tieuDe":"Đánh Chết Không Tin Là Chết","tomTat":"Thạch Hạo tuyên bố đã giết Hư Không Vương Thú, nhưng sinh linh dị giới khẳng định đối phương đang niết bàn, hòa cùng hư không và gần như không thể bị sát thương, khiến cả tu sĩ Thiên Thần thư viện cũng nghi ngờ. Biết trạng thái ấy vốn cực kỳ khó phá, Thạch Hạo suy đoán chiến quả của mình có liên quan đến tiểu nhân ngồi trên đóa hoa đại đạo. Yêu Nguyệt chế giễu lời tuyên bố của hắn, còn Vương Hi xấu hổ và khuyên hắn bớt nói. Thạch Hạo không cố chứng minh vì cho rằng sự hoài nghi hiện tại có thể giúp hắn tránh bị Phong tộc truy xét chuyện Phong Hành Thiên. Sau đó hắn khiêu khích Mạc Đạo, đối thủ áo trắng đang giao chiến bất phân thắng bại với Vương Hi. Một hậu duệ vương tộc dị giới có ba đầu sáu tay và hai đạo tiên khí bỏ đối thủ để tấn công Thạch Hạo, nhưng bị hắn áp đảo bằng tốc độ cùng sức mạnh thân thể. Thạch Hạo quật nát thân thể kẻ địch rồi phóng kiếm khí chém rơi đầu, khiến toàn chiến trường thất thần."},{"chuong":1128,"tieuDe":"Thể Thuật","tomTat":"Những người quan chiến dùng thiên nhãn nhìn rõ huyết nhục của Thạch Hạo đã đạt cực hạn dưới Thiên Thần cảnh, vì thế nhận lầm hắn là một thể tu có thành tựu hiếm thấy. Họ giải thích thể thuật là cổ pháp rèn thân thể cần thần dược, Trường Sinh dược và máu chân linh Bất Hủ, nhưng tỷ lệ thất bại cao đến mức ngay cả Trường Sinh gia tộc cũng ít khi cho đệ tử theo đuổi. Yêu Nguyệt dùng thân thể cường tráng của Thạch Hạo để trêu chọc Vương Hi, khiến Vương Hi lỡ lời rồi đỏ mặt. Thạch Hạo không đính chính hiểu lầm về mình mà liên tục khiêu khích thiếu niên áo trắng, buộc người này rời cuộc đối đầu với Vương Hi. Thiếu niên ấy được xác nhận là Mạc Đạo của Mạc gia, người cùng chị gái Mạc Tiên đều tu thành ba đạo tiên khí và được gọi là tuyệt đại song kiêu. Theo đề nghị của Vương Hi và người Thiên Thần Thư Viện, Mạc Đạo đồng ý chỉ dùng hai đạo tiên khí để chứng minh tu pháp có thể trấn áp thể thuật. Khi Mạc Đạo tuyên bố muốn thu Thạch Hạo làm tùy tùng, Thạch Hạo đáp lại bằng ván cược rằng kẻ thua phải cam nguyện làm người hầu."},{"chuong":1129,"tieuDe":"Áo Bào Trắng","tomTat":"Thạch Hạo tiếp tục gọi Mạc Đạo là gã sai vặt và buộc đối phương cam kết sẽ nhận thua nếu thất bại. Tuân theo điều kiện chỉ dùng hai đạo tiên khí, Mạc Đạo lần lượt diễn hóa đàn Chu Tước, dựng lao tù Ngũ Hành và triển khai Tụ lý càn khôn để áp chế đối thủ. Thạch Hạo dùng thần lực đánh tan hỏa thuật, dung hợp Côn Bằng pháp với Bảo thuật Lôi Đế để xuyên thủng lực Ngũ Hành, rồi đánh nổ không gian trong tay áo của Mạc Đạo. Vương Hi công khai đứng về phía người cùng Thiên Thần Thư Viện, trong khi Lục Đà và Huyền Côn chăm chú quan sát thủ đoạn của sinh linh dị vực. Mạc Đạo sau đó tiết lộ những đạo thuật mình vừa sử dụng đều là chiến lợi phẩm từng bị thế giới bên kia cướp khỏi Cửu Thiên Thập Địa. Lời tiết lộ khiến phía Thiên Thần Thư Viện biến sắc và khiến Thạch Hạo từ bỏ ý định tiếp tục thăm dò. Hắn quyết định chuyển sang thủ đoạn mãnh liệt nhất để sớm phân định thắng bại."},{"chuong":1130,"tieuDe":"Bắt Giữ","tomTat":"Thạch Hạo áp sát Mạc Đạo bằng ưu thế thể phách và pháp lực miễn dịch, trong khi Mạc Đạo kết chín loại pháp ấn để hợp nhất chín bảo thuật thành một đòn mạnh. Nhờ từng giao chiến với một thành viên Hoàng tộc có năng lực tương tự, Mạc Đạo sớm nhận ra nguy cơ và chủ động kéo giãn khoảng cách. Hai người tuân theo ước định chỉ sử dụng hai đạo tiên khí, giao chiến hơn trăm chiêu mà chưa phân thắng bại. Mạc Đạo sau đó dùng các pháp ấn cổ không trọn vẹn để tạm thời quấy nhiễu pháp lực miễn dịch rồi phản công bằng cổ thiên công. Thạch Hạo kiềm chế không thi triển Lục Đạo Luân Hồi Thiên Công, tự đánh tan ảnh hưởng của pháp ấn và khôi phục năng lực miễn dịch. Hắn ép Mạc Đạo vào cận chiến, đánh đối phương thổ huyết và trọng thương trước khi khóa giữ. Chương kết thúc khi Thạch Hạo yêu cầu Mạc Đạo thực hiện lời thua cuộc và làm tôi tớ của mình."},{"chuong":1131,"tieuDe":"Nguyện Thua Cuộc","tomTat":"Sau cuộc quyết đấu chỉ vận dụng hai đạo tiên khí, Mạc Đạo bị Thạch Hạo bắt sống và phong ấn hoàn toàn. Sinh linh dị vực vây quanh đòi cứu người, còn các học viên Thiên Thần Thư Viện tiến lên bảo vệ Thạch Hạo, khiến hai phe suýt bùng nổ hỗn chiến. Mạc Đạo ngăn đồng bạn gây rối và thừa nhận rằng nếu vẫn chỉ dùng hai đạo tiên khí thì tái đấu cũng khó thay đổi kết quả, dù hắn vẫn tự tin khi sử dụng đủ ba đạo tiên khí. Thạch Hạo nhắc lại giao ước buộc người thua phải làm tôi tớ nhưng cho phép Mạc Đạo khiêu chiến lại để giành tự do. Vì không muốn thất tín, Mạc Đạo chấp nhận đi theo Thạch Hạo. Thạch Hạo lập tức định dùng hắn ứng chiến với những người tu ra ba đạo tiên khí, trong khi một nhóm người dị vực sùng bái Mạc Đạo cũng tuyên bố muốn cùng hắn chịu khổ."},{"chuong":1132,"tieuDe":"Hỗn Chiến","tomTat":"Sau khi thất bại, Mạc Đạo chấp nhận đi theo Thạch Hạo dù những người trẻ tuổi đến từ Dị vực quyết liệt phản đối. Lục Đà, Yêu Nguyệt và Huyền Côn chủ trương giết tù binh để trừ hậu họa, nhưng Thạch Hạo muốn giữ lại kỳ tài đã tu thành ba đạo tiên khí. Mạc Đạo chủ động giao Bao Hàm Hồn tháp chứa một phần dấu ấn nguyên thần của mình, còn Vương Hi kiểm tra và xác nhận bí bảo không có vấn đề. Tào Vũ Sinh và Tiểu Thỏ Tử đồng thời nhận ra nhiều dấu hiệu quen thuộc, bắt đầu nghi ngờ người đã đổi dung mạo chính là Thạch Hạo sống sót trở về từ Thái Sơ cổ quáng. Khi các sinh linh Dị vực đồng loạt tấn công, Mạc Đạo nhận bảo vệ Thạch Hạo nhưng từ chối chủ động sát hại người cùng giới. Cuộc hỗn chiến giữa những kỳ tài hai thế giới bùng nổ, khiến chiến trường và núi non xung quanh bị tàn phá dữ dội. Trước sự xuất hiện liên tiếp của cường giả ba đạo tiên khí và một sinh vật kỳ dị cực mạnh, Thạch Hạo quyết định bộc lộ thực lực cuối cùng để đại khai sát giới."},{"chuong":1133,"tieuDe":"Tam Đầu Vương","tomTat":"Thạch Hạo đối diện Tam Đầu Vương, một con nhện khổng lồ có ba đầu và ba đạo tiên khí, được người của Thiên Thần Thư Viện nhận ra là sinh linh hung ác từng mang danh vô địch trong sách cổ. Sau khi xác định đối phương đến từ cổ giới thần bí và không thuộc các cổ vực sau Biên Hoang, hắn quyết định tuyệt sát nhưng vẫn che giấu đạo tiên khí thứ ba để lợi dụng sự khinh địch của nó. Tam Đầu Vương vừa giao chiến với Thạch Hạo vừa chuyển mục tiêu sang Mạc Đạo, người bị nó coi là kẻ phản bội thế giới cũ. Những người áo đen mang tử vong minh khí xuất hiện cản đường, nhưng Thạch Hạo đánh chết một kẻ rồi tiếp tục truy kích con nhện. Khi Mạc Đạo bị Tam Đầu Vương và một chí tôn trẻ tuổi dị vực vây đánh, Vương Hi cùng Huyền Côn lần lượt ra tay cứu viện, khiến toàn chiến trường bùng nổ đại hỗn chiến. Thạch Hạo vượt qua mạng nhện và áp sát đối phương, nhưng Tam Đầu Vương lập tức thi triển Năm tháng thay đổi, tạo ra vô số mảnh vỡ thời gian và tuyên bố bảo thuật này được thu hoạch từ Cửu Thiên Thập Địa."},{"chuong":1134,"tieuDe":"Ác Chiến","tomTat":"Tam Đầu Vương mở đầu cuộc ác chiến bằng bảo thuật thời gian, nhưng Thạch Hạo dựa vào hiểu biết cùng lĩnh vực để hóa giải và tiếp tục giấu thủ đoạn tuyệt sát. Khi giao tranh lan rộng, Mạc Đạo dùng xích liên cùng biển lửa trợ chiến, còn nhiều chí tôn trẻ tuổi dị vực tập trung công kích Vương Hi và Yêu Nguyệt. Yêu Nguyệt gọi Lục Đà, Huyền Côn và Vương Hi hợp lực phản công, khiến chiến trường biến thành cối xay thịt; bảo mệnh phù của Thiên Thần Thư Viện và thủ đoạn phía dị vực cứu được một số người, nhưng vẫn có tu sĩ chết thật. Thạch Hạo sau đó dẫn Tam Đầu Vương vào sâu trong sơn mạch và bộc lộ ba đạo tiên khí, khiến Mạc Đạo hoàn toàn thừa nhận khoảng cách thực lực giữa hai người. Trong trận quyết đấu riêng, Bảo thuật Liễu Thần xuyên thủng thân thể Tam Đầu Vương và phá thế bao phủ của mạng nhện thiên phú. Tam Đầu Vương vận chuyển Vạn Chu Ma Công câu thông lực lượng Ngân hà, còn Thạch Hạo dùng sáu thức mở đầu của Lục Đạo Luân Hồi trực diện đối kháng, làm hư không nứt vỡ nhiều dặm. Cuối chương, hai bên lao vào cận chiến đẫm máu và Thạch Hạo túm được một chân nhện của đối thủ, nhưng trận đấu vẫn chưa phân thắng bại."},{"chuong":1135,"tieuDe":"Đỉnh Phong Đại Chiến","tomTat":"Thạch Hạo dùng sức mạnh thân thể bẻ gãy một chân của Tam Đầu Vương nhưng cũng bị lông nhện kịch độc xuyên thủng hai tay. Hắn vận dụng cốt văn trong Nguyên Thủy Chân Giải để khử độc và tái sinh huyết nhục, trong khi đối thủ nhanh chóng mọc lại chân. Tam Đầu Vương thi triển Vạn Chu Ma Công, còn Thạch Hạo dùng sáu thức mở đầu của Lục Đạo Luân Hồi đối kháng. Một tuổi trẻ chí tôn đã tu thành ba đạo tiên khí bất ngờ phục kích khiến Thạch Hạo bị thương, nhưng Mạc Đạo kịp ra tay chặn người này và tách trận chiến thành hai chiến đoàn. Tam Đầu Vương tiếp tục dùng Sư Tử Hống, song Thạch Hạo lấy duy nhất động thiên phòng hộ rồi kích hoạt pháp lực miễn dịch để áp sát, dồn áo nghĩa Côn Bằng vào một quyền xuyên thủng thân thể đối phương. Khi Vô Úy Sư Tử Ấn không bị pháp lực miễn dịch hóa giải, Thạch Hạo hóa thành Côn Bằng trực diện quyết đấu và đánh tan hình thể sư tử, nhưng sinh tử của Tam Đầu Vương vẫn chưa được xác nhận."},{"chuong":1136,"tieuDe":"Ngộ Pháp","tomTat":"Vô Úy Sư Tử bị đánh nổ thành mưa máu, khiến Tam Đầu Vương mất đầu sư tử và một trong ba sinh mệnh, trong khi thời gian miễn dịch pháp lực của Thạch Hạo cũng vừa kết thúc. Từ biểu hiện của Vô Úy Sư Tử Ấn và những pháp ấn Mạc Đạo từng dùng, Thạch Hạo nhận ra loại thủ đoạn này chỉ có thể quấy nhiễu tức thời năng lực đặc thù của hắn. Tam Đầu Vương tiếp tục tấn công bằng lông nhện, ba đóa đại đạo chi hoa, ngũ sắc thần văn bẩm sinh và Vạn Chu Ma Công, khiến Thạch Hạo bị thương nhưng không thể phá vỡ hoàn toàn duy nhất động thiên. Qua đó, nó nhận ra động thiên của Thạch Hạo là kết quả dung hợp mười động thiên theo một con đường từng được suy diễn ở kỷ nguyên trước nhưng chưa ai trong gia tộc nó luyện thành. Giữa áp lực chiến đấu, Thạch Hạo thu nhỏ duy nhất động thiên quanh thân rồi khắc cốt văn Nguyên thủy chân giải, Côn Bằng pháp, Lôi Đế pháp cùng nhiều phù hiệu khác lên vách động thiên, mở ra một hướng diễn hóa riêng. Hắn dùng Tam Đầu Vương để kiểm nghiệm pháp môn vừa thôi diễn, đánh tan các thần thông và phù văn hộ thể của đối thủ, sau đó phá hủy cả thân nhện lẫn chiếc đầu tái hiện cuối cùng, khiến Tam Đầu Vương hoàn toàn mất khả năng phục sinh."},{"chuong":1137,"tieuDe":"Kinh Sợ","tomTat":"Thạch Hạo dùng quyền pháp đánh nổ Tam Đầu Vương, khiến Mạc Đạo và sinh linh hai phe đều chấn động. Chí tôn trẻ tuổi dị vực đang giao chiến với Mạc Đạo lập tức bỏ chạy, thiêu đốt tinh khí thần và thúc giục cổ phù để tăng tốc. Dù Thạch Hạo triển khai đôi cánh Côn Bằng truy đuổi, đối phương vẫn kịp nhảy lên cổ trận đài và được truyền tống khỏi chiến trường, đồng thời thề sẽ báo tin cho Hoàng tộc. Sau cuộc truy kích, duy nhất động thiên của Thạch Hạo bất ngờ nứt ra vì các phù văn được khắc vào đó vẫn chưa trọn vẹn. Thạch Hạo quay lại nơi Tam Đầu Vương tử trận, vác chiếc chân nhện khổng lồ còn sót lại tiến vào chiến trường chính. Chiến lợi phẩm này khiến người của Thiên Thần Thư Viện lẫn dị vực sửng sốt, đồng thời làm nhiều người tin rằng trước đó Thạch Hạo thật sự đã giết hư không thú. Chiến tích giết hai chí tôn trẻ tuổi tu ra ba đạo tiên khí trong một ngày khiến Thạch Hạo được nhìn nhận như một yêu nghiệt đủ sức sánh với tuyệt thế Hoàng tộc dị vực."},{"chuong":1138,"tieuDe":"Chiến Đấu Kết Thúc","tomTat":"Thạch Hạo trở lại chiến trường cùng chân nhện bị chặt của Tam Đầu Vương, khiến hai phe xác nhận vị Vương tộc dị vực đã chết nhưng phần lớn lại tưởng Mạc Đạo là người hạ sát. Được Vương Hi nhắc về giá trị luyện dược của di hài, Thạch Hạo sai Mạc Đạo đoạt lại chân nhện rồi cất vào lò luyện đan, trong khi cả hai phe đều thu máu để chuẩn bị suy diễn chân tướng. Khi giao tranh tiếp diễn, Thạch Hạo điều Mạc Đạo hỗ trợ Huyền Côn, Vương Hi và nhiều vị trí khác, nhanh chóng phá vỡ thế cân bằng. Một thủ lĩnh dị vực tu thành ba đạo tiên khí trực tiếp đấu quyền với Thạch Hạo nhưng bị phế một cánh tay, buộc phải ra lệnh rút quân. Tu sĩ Cửu Thiên Thập Địa lập tức chuyển sang truy sát đối phương. Sau đó Càn Khôn Đại và Thập Giới Đồ cùng phát động để bảo vệ hai phe, khiến thế giới diễn hóa giải thể và mọi người trở lại hiện thực. Tại ngọn núi màu đen, Tuyết bạch khô lâu kinh động khi biết Tam Đầu Vương đã chết, rồi nhận ra Hư Không Thú cũng không sống sót trở về."},{"chuong":1139,"tieuDe":"Chung Cực Địa","tomTat":"Tuyết bạch khô lâu nhận tin Tam Đầu Vương đã chết, Hư Không Thú mất tích và Mạc Đạo phản bội, nhưng không thể triển khai bí pháp vì bị pháp tắc thế giới áp chế. Càn Khôn Đại và Thập Giới Đồ đối đầu trong thời gian ngắn, tạo ra dư âm nghiền nát nhiều pháp khí cùng phần máu Tam Đầu Vương mà phe dị vực đã thu giữ. Biết không thể tiếp tục hành động, Tuyết bạch khô lâu dẫn đoàn sinh linh dị vực rút về đường nối, trong khi những tồn tại phía bên kia đe dọa sẽ lật đổ cả thế giới khi chân chính giáng lâm. Sau đó, một đại nhân vật mở kim sắc đại đạo và sinh linh già yếu dùng Thập Giới Đồ gia trì, đưa học sinh Thiên Thần Thư Viện tới nơi sâu nhất của đại lục trôi nổi giữa vũ trụ. Tại chung cực địa, các trưởng lão cho biết vùng phế tích này vừa có cơ duyên vừa có tử vong ma uyên, để mỗi người tự quyết định có mạo hiểm hay không. Gần như toàn bộ thiên tài lần lượt bước lên Cổ Thiên đài và biến mất tới những hành trình không thể dự đoán. Sau khi cân nhắc nguy cơ có thể vĩnh viễn thất lạc, Thạch Hạo vẫn cắn răng bước lên đài rồi lập tức biến mất."},{"chuong":1140,"tieuDe":"Vãng Sinh","tomTat":"Thân thể cùng thần hồn Thạch Hạo bị phân giải thành vô số hạt căn bản phát sáng, đưa hắn rời khỏi thế giới vốn có và nhìn thấy dòng sông thời gian phản chiếu nhiều thời đại. Bóng tối vô biên dần ăn mòn dòng sông, trong khi hàng loạt lao tù giống mật thất từng giam Nguyên Thần hắn từ nơi tối tăm rơi xuống và khuấy động sóng lớn. Một vòng xoáy quang minh hỗn độn xuất hiện giữa hắc triều, hút Thạch Hạo vào nơi sâu nhất rồi khiến hắn mất tri giác. Khi tỉnh lại, hắn đã khôi phục hình thể tại một cổ địa hoang phế bên hỗn độn và bắt đầu khảo sát những cung điện thần kim mang dấu tích của cuộc đại chiến vượt cấp nhân gian. Đoàn hỏa ẩn trong cơ thể hắn hóa thành gương, soi các dấu vết công kích và ghi lại khí thế đại đạo còn sót lại. Sau đó, Thạch Hạo gặp một nữ tử mang khí tức Tiên đạo trong kim loại cổ cung đầy sinh khí; nàng nói mình hiện chỉ là dấu ấn tan nát, mời hắn dùng tiên nhưỡng và xác nhận quá trình hắn đang trải qua là vãng sinh cùng Luân Hồi."},{"chuong":1141,"tieuDe":"Luân Hồi","tomTat":"Thạch Hạo nhớ lại việc mình hóa thành một hạt nhỏ bên dòng sông thời gian rồi bị vòng xoáy hút đi, từ đó nghi ngờ bản thân đã bước vào Luân Hồi. Nữ tử bên bàn đá giải thích rằng Luân Hồi không nhất thiết là chết rồi chuyển sinh mà có thể là một đoạn trải nghiệm nằm ngoài quỹ tích sinh mệnh ban đầu. Nàng thừa nhận mình không còn là tiên, chỉ là một dấu ấn tan nát với ký ức và nhận thức không đầy đủ. Sau đó, nàng mời Thạch Hạo uống tiên nhưỡng chứa kinh văn, pháp tắc, binh khí, sinh linh và nhiều con đường tu hành của Tiên cổ. Thạch Hạo mất nhiều ngày mới uống hết chén rượu và sống sót qua nguy cơ nổ tung thân thể, nhưng được cảnh báo không nên rập khuôn những con đường mà cường giả Tiên cổ từng đi. Cuối cùng, nữ tử cho hắn thử lay động bầu rượu đá và cho biết nếu hắn cầm được nó thì một biến cố lớn bằng trời, có ảnh hưởng cực kỳ sâu xa, sẽ phát sinh."},{"chuong":1142,"tieuDe":"Cổ Kim Tương Lai","tomTat":"Thạch Hạo nhận ra phần lớn phù hiệu, cổ kinh và huyền nghĩa từng cảm nhận trong tiên nhưỡng đã trở nên mơ hồ, còn nữ tử bên bàn đá giải thích rằng Tiên Cổ pháp chỉ có thể dùng để đối chiếu sau khi hậu thế tự mở con đường riêng. Dù được cảnh báo rằng chạm vào Bầu rượu đá có thể khiến mình hóa thành tro bụi hoặc rơi vào một trận kịch biến gần như tuyệt sát, hắn vẫn quyết định thử. Bàn tay Thạch Hạo lập tức rạn nứt, nhưng hỗn độn khí và tiên vụ từ bầu rượu giúp tình trạng ổn định, cho phép hắn vận chuyển Liễu Thần pháp trị thương rồi cưỡng ép nhấc bầu lên. Sau khi uống tiên nhưỡng và tiếp nhận vô số hư ảnh binh khí, sinh linh cùng kinh văn, hắn bất ngờ bị một cường giả có chân thân ở vạn cổ trước cảm ứng. Nam tử ấy đưa thần giác vượt Dòng sông thời gian, tuyên bố thời gian là một vòng có thể đảo ngược và thừa nhận từng thuận thế xóa bỏ nhiều nhân vật tỏa sáng trong lịch sử. Bất chấp lời cảnh báo về nhân quả kinh thiên, hắn vẫn chuẩn bị giết Thạch Hạo trước khi trưởng thành. Đúng lúc cuộc thảo phạt sắp bắt đầu, một cô gái đeo mặt nạ quỷ hiện thân giữa quang vũ và hỗn độn khí, ép sụp cổ kim tương lai và đánh gãy Dòng sông lịch sử."},{"chuong":1143,"tieuDe":"Bạch Y Tuyệt Thế","tomTat":"Một nữ tử áo trắng đeo mặt nạ quỷ xuất hiện ở hạ du dòng sông thời gian và thể hiện sự quan tâm đặc biệt đối với Thạch Hạo. Nhận ra người đến cứu mình không phải Liễu Thần, Thạch Hạo nhớ lại viễn cảnh mọi thân nhân, bằng hữu và cố nhân đều mất, nhưng vẫn kiên quyết tin rằng tương lai có thể thay đổi. Nam tử như quân vương ở thượng du chú ý tới nữ tử áo trắng rồi tung hàng nghìn hàng vạn đại thần thông theo dòng lịch sử đánh xuống. Nàng thi triển Vạn Hóa Tiên Quyết bằng một pháp ấn và một chưởng, khiến toàn bộ công kích sụp đổ rồi hóa thành hư vô. Mặt nạ đồng xanh của nàng được hé lộ là chí bảo luyện từ đồng thau và tinh hoa tiên kim, có thể biến thành chiếc nhẫn, Tiên Kiếm hoặc đại đạo bảo bình. Sau khi hóa giải đòn đánh, nữ tử áo trắng ném mặt nạ ngược dòng thời gian, khiến nó hóa thành màn trời phá nát tinh đấu và tầng tầng trấn áp nam tử ở thượng du."},{"chuong":1144,"tieuDe":"Không Thể Khinh Nhờn","tomTat":"Nam tử giáp trụ hiện chân hình, vận dụng chưởng lực, quyền pháp và đại đạo quy tắc công kích mặt nạ đồng xanh nhưng bị phản chấn rách gan bàn tay. Một giọt lệ từ mặt quỷ trên mặt nạ hóa thành đại dương nhấn chìm hắn, buộc hắn đốt cháy sức mạnh để sấy khô biển lệ. Khi hắn dùng chiếc đuôi bọc giáp đánh mặt nạ xuôi về hạ du, nữ tử áo trắng ổn định nó rồi biến thành Tiên Kiếm, chém nứt giáp trụ và khiến hai tay hắn chảy máu. Nam tử dùng huyết dịch bất diệt kết thành sát trận quanh nàng, muốn lưu lại dấu ấn để truy tìm trong tương lai, nhưng Tiên Kiếm nhanh chóng phá trận và chém vỡ chiến y tiên gia. Nữ tử áo trắng tiếp tục kết bảo bình pháp ấn, dung hợp quang bình với bảo bình do Tiên Kiếm biến thành để hút huyết quang, thần thông và bí thuật của đối thủ. Dù nam tử triển khai cấm kỵ bí pháp phản công, bảo bình vẫn đánh sụp giáp trụ, khiến thân thể hắn nứt thành bốn mảnh và văng ngược về thượng du dòng sông thời gian."},{"chuong":1145,"tieuDe":"Tạm Biệt","tomTat":"Nữ tử áo trắng dùng đại đạo bảo bình luyện hóa tinh huyết đã hấp thu và phóng tiên kiếp lực đánh tan pháp thân của nam tử, khiến các mảnh giáp trụ tiên kim văng vào phế tích và được Thạch Hạo thu lấy. Thất bại này phản chấn chân thân của nam tử tại cuối Tiên cổ, làm mi tâm hắn rạn nứt và chảy máu. Chân thân tiếp tục hiện lên trong cổ miếu ở thượng du dòng thời gian, tụng chân kinh giữa vô lượng tinh hà, trong khi hai bóng đen khổng lồ dần xuất hiện giữa khói đen phía sau hắn. Để ngăn chúng vượt xuống hạ du, nữ tử áo trắng thi triển thiên công tái tạo chân ngã và toàn lực chặt đứt dòng sông thời gian, khiến cổ miếu cùng các bóng đen biến mất nhưng bản thân nàng cũng bị thương. Sau đó, nàng dùng mưa ánh sáng đưa Thạch Hạo ra khỏi dòng sông, nhân quả và phạm vi thôi diễn. Nàng dự báo hắn sẽ phải chịu con đường gian nan, đau khổ hơn mọi người và nhắc tới một người độc đoán vạn cổ. Thạch Hạo cố nhìn rõ dung mạo nàng nhưng không thể, còn nàng nói lời tạm biệt rồi hóa thành mưa ánh sáng biến mất."},{"chuong":1146,"tieuDe":"Lối Về","tomTat":"Ngồi bên dòng sông thời gian, Thạch Hạo hồi tưởng cuộc quyết chiến giữa nữ tử áo trắng và nam tử như quân vương, đồng thời lo lắng trước tương lai đầy kinh biến cùng Ma Ảnh đáng sợ đứng phía sau. Hắn vẫn tin mọi chuyện chưa xảy ra đều có thể nghịch chuyển, rồi nhận từ nữ tử bên bàn đá những mảnh chiến y tiên kim còn lưu dấu vết đại đạo. Sau khi uống cạn rượu chứa kinh văn, Thạch Hạo chứng kiến nữ tử hóa thành phù văn và nhận ra nàng chỉ là một ấn ký tinh thần. Hắn hợp nhất các thần thông từ Chí Tôn cốt để tác động thời gian, sau đó bị hắc động giữa vòng xoáy hỗn độn cuốn đi và trở về tế đàn. Tại đây, nhóm thứ đầu Thiên Thần thư viện đang cưỡng ép những người yếu hơn giao ra cơ duyên, khiến Thái Âm Ngọc Thỏ và Tào Vũ Sinh đứng lên phản kháng. Khi nghe đối phương coi thường Hoang và thấy cố nhân bị khi dễ, Thạch Hạo truyền âm cho Mạc Đạo tham gia trao đổi, đồng thời ra lệnh nâng giá gấp đôi để đáp trả."},{"chuong":1147,"tieuDe":"Giặc Cướp Giao Lưu","tomTat":"Sau hành trình thần dị trên tế đàn, Mạc Đạo nhìn thấy những hình chạm khắc về chiến tranh cổ đại và một phần chân tướng lịch sử, khiến nhận thức của hắn dao động dù vẫn còn hoài nghi. Thạch Hạo kỳ vọng danh tiếng của Mạc Đạo tại thế giới phía sau Biên Hoang sẽ giúp hắn trở thành người truyền bá chân tướng và tạo ra biến động từ bên trong. Theo lệnh Thạch Hạo, Mạc Đạo giải vây cho Tào Vũ Sinh, người đang dùng thân thể làm pháp bàn để hiển lộ tiên thiên sát trận cùng Hỗn Độn kiếm khí. Mạc Đạo tiếp tục đánh bại nhóm người gây sự nhưng không giết ai, rồi biến cuộc giao lưu thành một màn ép giao nộp thần thông, pháp khí và tạo hóa. Thái Âm Ngọc Thỏ, Tào Vũ Sinh và Thanh Y cũng tham gia vơ vét những người bại trận. Khi một kẻ có liên hệ với Vương gia dùng Kim Cương trác và thân phận người theo đuổi Vương Hi để miệt thị, Thạch Hạo đánh trọng thương y rồi tuyên bố sẽ bắt Vương Hi nếu lời uy hiếp ấy đại diện cho Vương gia."},{"chuong":1148,"tieuDe":"Xung Đột Mới Nổi Lên","tomTat":"Thạch Hạo xác nhận kẻ vừa đối đầu chỉ thuộc một gia tộc thân cận với Vương gia rồi đá nổ nửa thân trên của hắn, khiến mâu thuẫn giữa các phe tiếp tục gia tăng. Yêu Nguyệt công chúa nhân cơ hội công khai lôi kéo Thạch Hạo và hứa giúp tháo Kim Cương trác, còn Vương Hi trở về, thận trọng quan sát rồi hỏi nguyên nhân. Mạc Đạo lục soát những người vừa trở lại để tìm cơ duyên nhưng phần lớn tạo hóa đã được hấp thu, đồng thời nghe kể về một viên bất diệt tiên đan có sinh mệnh đã bay khỏi lò luyện đan. Sau đó, Mạc Đạo tìm được hai bộ ngọc thạch kinh thư màu tím, song hắn và Thạch Hạo buộc phải giao chúng cho các trưởng lão Thiên Thần Thư Viện bảo quản và giải mã. Sự việc khiến Thạch Hạo quyết tâm học thấu cổ văn Tiên Đạo để tự mở bộ kinh thư mình mang từ ba ngàn châu. Khi tế đàn không còn người sống trở về, các trưởng lão đưa đoàn người lên cổ lão chiến thuyền, vượt vũ trụ trở lại Vô Lượng Thiên và Thiên Thần Thư Viện. Sau khi họ rời đảo, một bóng đen bí ẩn tuyên bố Tiên Đạo ngọc thạch thư đang lần lượt xuất thế tại nhiều nơi và đại thế đã bắt đầu."},{"chuong":1149,"tieuDe":"Phong Ba Loạn","tomTat":"Chiến thuyền từ tiên gia chiến trường trở về Thiên Thần Thư Viện, mang theo bốn bộ ngọc thạch thư cùng những tin tức gây chấn động về sinh linh dị vực và các trận chiến vừa qua. Thạch Hạo bí mật gặp đại trưởng lão rồi trở về tịnh thổ của Vương Hi, nơi hắn trở thành tâm điểm của hàng loạt lời đồn và những cuộc lôi kéo nhắm cả vào hắn lẫn Mạc Đạo. Các trưởng lão đưa Mạc Đạo đi thẩm vấn, nhưng việc cưỡng ép sưu Nguyên Thần kích hoạt dấu ấn Bất Hủ giả, buộc họ dùng Thập Giới Đồ và Cửu Hoàng lô trấn áp rồi đưa hắn vào Hoàng Huyết trì chữa thương. Thạch Hạo sau đó công khai đoạt Mạc Đạo trở về, cảnh cáo các phe không được tiếp tục có ý đồ và nhận nhiệm vụ âm thầm khai thác tình báo dị vực. Người Vương gia nhận ra hắn là người từng sống sót khỏi Thái Sơ cổ quáng thông qua Kim Cương trác, từ đó nhòm ngó cả bí mật cổ quáng lẫn Mạc Đạo. Khi lớp trẻ Vương gia tuyên bố chiếc vòng khiến hắn suốt đời là tôi tớ của Vương Hi, Thạch Hạo nổi giận và quyết xả đứt nó để rửa nhục. Cuối chương, tin đồn hắn đã hạn chế Vương Hi, phong nàng trong động phủ và thậm chí bái thiên địa với nàng lan khắp thư viện, nhưng chân tướng vẫn chưa được xác nhận."},{"chuong":1150,"tieuDe":"Đột Kích Ngược","tomTat":"Tin Vương Hi bị Thạch Hạo khống chế trong động phủ lan khắp Thiên Thần thư viện, khiến đông đảo người ngưỡng mộ nàng và con cháu Vương gia kéo tới tịnh thổ. Trước cửa động phủ, Mạc Đạo hiển hóa ba đạo tiên khí, canh giữ phong ấn và khước từ mệnh lệnh của người Vương gia. Hắn còn vạch rõ tiên khí không thuần khiết của một số con cháu Vương gia được tạo từ phần còn sót lại trong di hài anh kiệt cổ đại, rồi dễ dàng đánh trọng thương những người dùng bảo thuật tấn công. Cao thủ Vương gia chuyển sang công kích động phủ nhưng dù núi đá rung chuyển, phong ấn vẫn không hề tổn hại. Yêu Nguyệt công chúa nhân cơ hội châm chọc rằng Vương Hi tự chọn nam nhân, khiến người Vương gia tức giận nhưng không dám trở mặt với tộc nhân của nàng. Cuối cùng, cửa đá mở giữa hỗn độn khí và Thạch Hạo bước ra, trực tiếp đáp trả lời trách mắng liên quan đến Kim Cương Trác cùng thân phận tôi tớ, đẩy mâu thuẫn với Vương gia lên công khai."},{"chuong":1151,"tieuDe":"Hung Hăng","tomTat":"Thạch Hạo bị nhiều thành viên Vương gia vây tại động phủ trong Thiên Thần Thư Viện, nhưng hắn đóng cửa đá và dựa vào cấm chế để ngăn cốt văn cùng xích thần trật tự phá vào. Sau khi một trưởng lão thư viện truyền âm, hắn mở cửa rồi công khai bác bỏ thân phận tôi tớ và mắng trả người Vương gia. Người trung niên Vương gia ra tay bắt hắn nhưng bị trưởng lão dùng bàn tay mang hỗn độn khí và hơi thở thời gian chặn lại. Thạch Hạo tiếp tục dùng chuyện quan hệ với Vương Hi để chọc giận Vương gia, còn Yêu Nguyệt công chúa tiếp lời chế giễu và tuyên bố sẽ tặng quà chúc mừng. Cuộc đối đầu đồng thời hé lộ Vương Hi được dự định gả cho một nhân vật tuyệt đại nhằm liên kết hai đại gia tộc trước nguy cơ đại loạn. Trưởng lão công bố đại trưởng lão đã ban pháp chỉ để Thạch Hạo sắp trở thành đệ tử Thiên Thần Thư Viện, qua đó xác lập sự bảo hộ của thư viện đối với hắn. Tuy nhiên, Thạch Hạo khiến mọi người sửng sốt khi tuyên bố bản thân vẫn đang cân nhắc có gia nhập thư viện hay không."},{"chuong":1152,"tieuDe":"Nói Dối","tomTat":"Pháp chỉ của Đại trưởng lão mời Thạch Hạo trở thành đệ tử Thiên Thần Thư Viện khiến toàn trường chấn động và buộc người Vương gia phải đánh giá lại hắn. Khi bị truy hỏi về Vương Hi, Thạch Hạo cố tình nói nàng đang ngủ say rồi dùng những lời mập mờ về chuyện tâm đầu ý hợp và cùng tu kỳ công, khiến các cao thủ Vương gia tưởng danh tiết của nàng đã bị tổn hại. Một số người nổi giận lao lên định giết hắn, nhưng vị trưởng lão nhận nhờ vả của Đại trưởng lão kịp thời ngăn cản. Vương Hi được đưa khỏi động phủ và giải thích rằng nàng đang dùng Tâm Mộng Cổ Kinh để nhập mộng ngộ đạo, còn Thạch Hạo chỉ hỗ trợ phần mở đầu. Nàng cũng phủ nhận lời đồn mình bị Thạch Hạo đánh lén và áp chế, qua đó làm rõ nguyên nhân của trạng thái ngủ say. Dù vậy, Vương gia vẫn yêu cầu bồi thường vì thanh danh của Vương Hi bị ảnh hưởng. Đại trưởng lão liền đề nghị họ gả Vương Hi cho Thạch Hạo, khiến cả gia tộc rơi vào thế khó chấp thuận mà cũng khó từ chối."},{"chuong":1153,"tieuDe":"Sáng Tỏ","tomTat":"Đại trưởng lão dùng đề nghị ghép đôi Thạch Hạo với Vương Hi để hóa giải xung đột, nhưng Vương gia và chính Vương Hi đều bác bỏ hôn sự. Khi người Vương gia tiếp tục gọi mình là tôi tớ, Thạch Hạo công khai phủ nhận quan hệ chủ tớ và lập cược rằng hắn có thể phá Kim Cương trác. Nhờ bảo thuật bảo vệ đầu cùng Nguyên Thần và lời điểm hóa trước đó của đại trưởng lão, hắn tay không xé đứt bảo trác pha tiên kim mà không bị thương. Những người Vương gia thua cược bị hắn gọi ngược là nô bộc, có người ho ra máu hoặc ngất đi vì tức giận và nhục nhã. Màn thể hiện này khiến Vương Hi, Lục Đà, Huyền Côn và Yêu Nguyệt nhận ra chiến lực đáng sợ của Thạch Hạo, đồng thời khiến đám đông tin rằng hắn thực sự đã giết Tam Đầu Vương, săn Hư Không Thú và thu phục Mạc Đạo. Các gia tộc lớn lập tức muốn chiêu mộ hắn, song phải kiềm chế vì đại trưởng lão Thiên Thần Thư Viện đã tiếp cận trước."},{"chuong":1154,"tieuDe":"Lựa Chọn Thời Khắc","tomTat":"Những người Vương gia thua đổ ước nhưng không chịu thỉnh tội hay tôn Thạch Hạo làm chủ, đành rời khỏi động phủ trong nhục nhã, còn quan hệ giữa Thạch Hạo và Vương Hi công khai rạn nứt. Theo chỉ thị của Thạch Hạo, Mạc Đạo phóng ba đạo tiên khí chấn nhiếp đám đông, trong khi Thanh Y và Tào Vũ Sinh đưa Thái Âm Ngọc Thỏ đi để tránh làm lộ thân phận của hắn. Tin tức về thất bại của Vương gia nhanh chóng lan khắp Thiên Thần Thư Viện, kèm theo lời đồn về vị hôn phu của Vương Hi và những thiên tài không lấy tiên khí làm chuẩn mực chiến lực. Thạch Hạo cùng Mạc Đạo chuyển tới một vùng tịnh thổ mới, nhưng Mạc Đạo vẫn giữ kín mọi thông tin về dị vực và thế giới phía sau Bất Hủ Sơn. Sau đó, đại đạo chi chung vang lên, triệu tập quần anh tới Thạch Lâm, nơi các trưởng lão cấp Chí Tôn cảnh báo đại loạn và chiến tranh đã cận kề. Thiên Thần Thư Viện quyết định sớm truyền tiên đạo kinh văn của kỷ nguyên trước, đồng thời yêu cầu học viên lựa chọn giữa tiên cổ pháp và kiếp này pháp. Các trưởng lão nhấn mạnh rằng cổ pháp rất khó tu trong thiên địa hiện thời, còn pháp đương thời cũng có con đường riêng đủ sức tạo nên cường giả tuyệt thế."},{"chuong":1155,"tieuDe":"Kiếp Này Pháp Cực Điểm","tomTat":"Các thiên kiêu mới vào Thiên Thần Thư Viện yêu cầu trưởng lão giải thích rõ hơn về cổ pháp và kiếp này pháp trước khi họ đưa ra lựa chọn ảnh hưởng cả đời. Lão đạo sĩ áo vàng gọi Tào Vũ Sinh lên làm ví dụ, buộc hắn phô bày những sát trận khắc trong máu thịt và qua đó chứng minh thành quả vượt cực cảnh Liệt Trận. Các trưởng lão giải thích rằng mọi cảnh giới hiện hành đều có thể được đẩy vượt giới hạn của cổ hiền, mở ra tầng thứ mới đủ sức đối đầu người tu thành tiên khí. Thạch Hạo tiếp tục được nêu làm hình mẫu nhờ từng phá nát mười động thiên rồi dung hợp thành duy nhất động thiên, một thành tựu vượt qua các đời tiên hiền. Sau đó, các trưởng lão chỉ rõ phần lớn thiên kiêu tu thành tiên khí đều dựa vào gia tộc, thân thể được phong ấn từ Tiên cổ hoặc môi trường cổ địa, bởi hoàn cảnh hiện tại không còn thích hợp để tự mình hoàn thành con đường ấy. Thiên Thần Thư Viện công bố tài nguyên dành cho cả hai lựa chọn, gồm kinh thư và tiểu thế giới Tiên cổ cho người học cổ pháp, cùng thành quả của những tuyệt đại nhân vật đi trước cho người theo kiếp này pháp. Dù bản thân là hình mẫu nổi bật của kiếp này pháp, Thạch Hạo bất ngờ chọn Tiên cổ pháp, khiến các trưởng lão nghi ngờ hắn muốn đồng thời đi cả hai con đường."},{"chuong":1156,"tieuDe":"Tiên Cổ Pháp","tomTat":"Bất chấp lời khuyên nên tận dụng thành tựu mười động thiên hợp nhất để tu pháp đương thời, Thạch Hạo kiên quyết lựa chọn Tiên cổ pháp và chấp nhận phải bắt đầu lại trong một hệ thống khác. Hắn muốn đi hết con đường cổ pháp rồi quay lại lĩnh ngộ pháp đương thời, dùng hai hệ thống xác minh lẫn nhau. Phần đông học viên chọn pháp đương thời, còn nhóm học Tiên cổ pháp tuy ít người hơn nhưng quy tụ nhiều cao thủ như Yêu Nguyệt công chúa, Lục Đà, Vương Hi, Thập Quan Vương, Trích Tiên, Thanh Y và Nguyệt Thiền. Tào Vũ Sinh cũng muốn sang nhóm cổ pháp nhưng bị lão nhân mặc đạo bào màu vàng cưỡng ép trở lại vì pháp đương thời phù hợp hơn với thiên phú của hắn. Nhóm Thạch Hạo được dẫn tới một di tích nằm sâu trong Thiên Thần Thư Viện, nơi bốn trưởng lão bắt đầu truyền dạy văn tự và ngôn ngữ Tiên cổ. Họ cho biết hệ thống hoàn chỉnh có tới trăm vạn chữ, mỗi chữ cô đọng một phần quy tắc hoặc đạo lý và được dùng để diễn tả đạo thuật, thần chú cùng đạo phù. Cuối cùng, bốn trưởng lão đưa ra bạch ngọc sơn khắc trăm vạn chữ để học viên tham ngộ, đồng thời tiết lộ phần đỉnh từng chứa 108 chữ cô đọng đại đạo chân nghĩa đã bị tước mất và toàn bộ số chữ ấy hiện đều thất truyền."},{"chuong":1157,"tieuDe":"Tiên Chi Chủng","tomTat":"Thạch Hạo cùng các đệ tử lên Bạch Ngọc Sơn tìm hiểu hệ thống chữ cổ Tiên Cổ, nhưng phần đỉnh từng chứa 108 chữ chung cực đã bị chém mất từ thời xa xưa. Tứ trưởng lão cho biết ngọn núi đã được các trưởng lão luyện hóa và lưu lại dấu ấn tinh thần để hỗ trợ ngộ pháp, song một đệ tử trẻ vẫn bị dị tượng đánh trọng thương vì chạm vào dấu ấn khi chưa hiểu chữ. Trong những ngày tiếp theo, Lục Đà đánh tan mười Thiên Long do chữ cổ tạo thành, Vương Hi dùng ba đạo tiên khí thiêu rụi cổ thụ vàng, còn Trích Tiên khiến mô hình vũ trụ cổ hiện ra. Thập Quan Vương công khai cây non Thế Giới Thụ để hỗ trợ lĩnh ngộ, trong khi Thanh Nguyệt giúp Thanh Y hiểu hơn vạn chữ và đạt thành tích cao nhất nhóm. Tứ trưởng lão nhận ra Thanh Nguyệt là mồi lửa do Chân Tiên chết đi để lại, đồng thời giải thích người tu Tiên Cổ pháp bắt buộc phải chọn tiên chủng để cùng bản thân tiến hóa và hợp đạo. Ông quyết định sau một thời gian sẽ dẫn các đệ tử tới Giới phần tìm tiên chủng, đồng thời thúc giục họ nâng cao thực lực để không bị Thánh Viện và Tiên Viện vượt qua."},{"chuong":1158,"tieuDe":"Thánh Viện Cùng Tiên Viện","tomTat":"Tứ trưởng lão giải thích rằng Thánh Viện và Tiên Viện là hai thư viện lánh đời đã trường tồn từ cổ xưa, chỉ được bên ngoài biết rõ mỗi khi mở cửa tuyển người. Tiên Viện cổ xưa hơn, lưu giữ nhiều pháp môn từ kỷ nguyên trước và dẫn dắt môn đồ tu cổ pháp trên con đường thành tiên. Thánh Viện thành lập muộn hơn, chỉ thu nhận tuyệt đại nhân kiệt và chuyên khai phá kiếp này pháp bằng cách vượt qua giới hạn của từng cảnh giới. Những lão quái vật thuộc hai viện còn tiến hành các thực nghiệm cực đoan như phục sinh di hài Tiên cổ hoặc phá bỏ tu vi của môn đồ để họ tu lại từ đầu. Hai viện sắp giao lưu với Thiên Thần Thư Viện và có thể tuyển đi những học viên xuất sắc phù hợp với đường lối của mình. Tứ trưởng lão cũng tiết lộ Nguyên Thanh từng bị loại trong khảo hạch nhưng vẫn được ban đạo thư, được các lão quái vật chỉ điểm và duy trì liên hệ với hai viện. Thạch Hạo nổi giận khi nhớ lại những việc Nguyên Thanh từng gây ra, đồng thời hiểu rằng mình đang được cảnh báo về hậu thuẫn khó lường của đối phương."},{"chuong":1159,"tieuDe":"Thanh Nguyệt Truyền Thuyết","tomTat":"Thạch Hạo biết Nguyên Thanh xuất thân từ hai viện, qua đó hiểu vì sao con cháu người này vẫn có thể vào Thiên Thần Thư Viện sau những chuyện đã xảy ra. Trong thời gian lĩnh hội văn tự Đại Đạo tại Bạch Ngọc Sơn, Thanh Y tiến bộ vượt trội nhờ Thanh Nguyệt diễm, còn Nguyệt Thiền cũng hưởng lợi vì hai nàng vốn là một thể chia đôi. Các trưởng lão xác định ngọn lửa xanh là mồi lửa Thanh Nguyệt Tiên Tử để lại khi chết trong kỷ nguyên trước, đồng thời hé lộ truyền thuyết nàng từng nghiên cứu độ kiếp pháp và có thể trở lại thế gian. Giá trị của mồi lửa cùng khả năng Thanh Y hợp nhất với Nguyệt Thiền khiến nhiều Trường Sinh thế gia và thế lực lớn tìm cách lôi kéo nàng. Sau một tháng, Tứ trưởng lão đưa lò luyện đan Tiên Cổ tới phế tích và công bố số Phạt Mạch đan còn chôn trong tro lò phải được tranh bằng thực lực. Thập Quan Vương dùng Long quyền đánh trọng thương người lao vào trước, rồi Vương Hi, Lục Đà, Trích Tiên, Yêu Nguyệt, Huyền Côn và các cao thủ khác hỗn chiến quanh miệng lò. Thạch Hạo sai Mạc Đạo mở đường nhưng bị những Chí Tôn khác ngăn cản; khi Thanh Y tới, cả Lục Đà lẫn Thạch Hạo đều mời nàng đồng hành. Cuối cùng, một đệ tử công khai khiêu chiến Thạch Hạo dưới tên Cửu Văn nhằm kiểm chứng chiến lực thật sự của hắn."},{"chuong":1160,"tieuDe":"Bức Bách","tomTat":"Một thanh niên đội Tử Kim quan đã tu thành hai đạo tiên khí công khai khiêu chiến Thạch Hạo, dùng lời khích bác và dụ Mạc Đạo phản chủ. Thạch Hạo nhận ra người này được cao thủ cấp Vương Hi, Lục Đà sai tới thăm dò nên lệnh Mạc Đạo ứng chiến. Mạc Đạo thi triển pháp chữ cổ hóa Hỏa Hoàng đối đầu Không Minh kính đồ nhái, đánh vỡ bảo kính rồi dùng lợi khí hình long xà chặt đứt đoản kiếm ẩn bên trong và chém ngang lưng đối thủ. Đồng thời kẻ ẩn danh tung thanh đồng khôi lỗi và bốn sinh linh thuộc các chủng tộc Thái Cổ mang bí bảo Trường Sinh gia tộc cùng vây đánh Thạch Hạo. Thạch Hạo căng duy nhất Động Thiên sát thân, tay không xé nát khôi lỗi, phá hủy toàn bộ bí bảo và đánh trọng thương cả bốn sinh linh trong khoảnh khắc mà không hề thi triển bảo thuật, khiến mục đích thăm dò pháp lực thất bại. Sau đó hắn giẫm nát thân thể thanh niên đội Tử Kim quan vừa khôi phục, chỉ chừa đầu lâu. Cuối cùng, nhóm tuổi trẻ Chí Tôn ba đạo tiên khí đích thân đạp hư không tiến tới, yêu cầu được nhìn thấy chân thân của Thạch Hạo."},{"chuong":1161,"tieuDe":"Chí Tôn Trẻ Tuổi","tomTat":"Lục Đà, Vương Hi, Huyền Côn, Thập Quan Vương và Yêu Nguyệt Công Chúa cùng tiến lên, muốn dùng giao thủ để xác nhận thân phận thật của Thạch Hạo. Thạch Hạo không còn e ngại việc dùng chân thân đối địch và công khai chấp nhận cả đơn đấu lẫn vây công, trong khi Mạc Đạo chủ động bước ra chặn Lục Đà. Mạc Đạo bộc lộ ba đạo tiên khí cùng hai binh khí, còn Lục Đà khiến tiên khí hóa thành đại thụ, tạo nên cuộc đối quyết dữ dội giữa sáu luồng tiên khí. Sau đó Vương Hi giành quyền giao chiến với Thạch Hạo, chất vấn lai lịch của hắn và tranh cãi về ân oán với Vương gia. Lời trêu chọc liên quan đến chuyện song tu khiến Vương Hi nổi giận, triệu hồi liên hoa bạc Hỗn Độn tấn công, nhưng Thạch Hạo dùng lá liễu xanh để đối kháng. Vương Hi tiếp tục lấy ra kiếm thai màu đen chứa Hắc Ám tiên kim, khiến Thạch Hạo nảy ý định dùng Đại La tiên kiếm phá hủy nó để đoạt tinh hoa. Cuối chương, Thạch Hạo ngưng tụ một bàn tay Pháp tướng màu vàng đất phủ kín bầu trời và chộp xuống Vương Hi."},{"chuong":1162,"tieuDe":"Bình Loạn Quyết","tomTat":"Vương Hi dùng hắc ám tiên kim kiếm và Phá Thiên Thức chống lại bàn tay lôi đình của Thạch Hạo, nhưng vẫn bị một tia điện truyền dọc kiếm thai ép phải lùi lại. Nàng công khai thi triển Bình Loạn Quyết, truyền thừa mạnh nhất của Vương gia đã trải qua mười ba đời không người luyện thành, khiến kiếm mang hóa thành hình người dẫn động lực lượng dị tượng. Thạch Hạo đáp trả bằng chân nghĩa Côn Bằng, vận chuyển sức mạnh Thái Âm và Thái Dương để đẩy lui Vương Hi và chống trực tiếp tiên kim kiếm. Việc Côn Bằng pháp xuất hiện khiến Thập Quan Vương, Yêu Nguyệt Công Chúa và Thanh Y bắt đầu nhận ra người giao chiến có thể là thiếu niên hạ giới từng bị cho là đã chết trong Thái Sơ cổ quáng. Khi Vương Hi sử dụng thêm một môn cổ thiên công, Thạch Hạo thi triển Lục Đạo Luân Hồi, làm toàn bộ người quan chiến chấn động trước truyền thừa của Chí Tôn cung điện. Sau cuộc va chạm, những cành màu vàng mang phù hiệu mọc ra từ hư không, chống lại kiếm thai rồi trói chặt Vương Hi và cầm cố nàng giữa hư không."},{"chuong":1163,"tieuDe":"Cầm Tiên","tomTat":"Thạch Hạo điều động những cành liễu màu vàng có sức sống mạnh để trói giữ Vương Hi, khiến nàng không thể thoát thân dù đã dùng hắc ám Tiên Kim kiếm, Nam Minh Ly Hỏa và thủ đoạn xé hư không. Hai bên tiếp tục điều động Linh Thân giao chiến, trong đó nhiều Linh Thân kết hợp bảo thuật của Thạch Hạo áp chế mười Linh Thân của Vương Hi. Côn Bằng pháp và Bảo thuật Liễu Thần khiến những người quan chiến nhận ra hắn chính là Hoang đến từ hạ giới, đồng thời xác nhận hắn chưa chết trong Thái Sơ Cổ Khoáng. Khi hai Linh Thân bị trọng thương, Vương Hi cho Nguyên Thần xuất khiếu và thi triển Bình Loạn Quyết ở trình độ cao thâm, hóa lực Nguyên Thần thành kiếm cương truy sát đối thủ. Thạch Hạo ban đầu né tránh bằng cực tốc của Côn Bằng pháp, sau đó dùng quyền ấn trực tiếp va chạm với Nguyên Thần kiếm thai. Trước sức ép của kiếm quyết, Chí Tôn huyết trong cơ thể hắn thức tỉnh, giúp hắn đồng thời chồng chất Thượng Thương, Luân Hồi và thần thông thứ ba có năng lực gia trì. Chương kết thúc khi mưa ánh sáng do ba loại bảo thuật tạo thành phủ kín chiến trường, còn kết quả cuộc đối đầu vẫn chưa được phân định."},{"chuong":1164,"tieuDe":"Chân Thân Đối Mặt","tomTat":"Ba loại bảo thuật do Thạch Hạo chồng lên nhau làm Nguyên Thần kiếm thai chưa đại thành của Vương Hi rạn nứt, gãy một đoạn và buộc nàng rút nguyên thần về thân thể. Thạch Hạo lập tức áp sát, dùng cành liễu màu vàng bắt giữ Vương Hi rồi công khai khôi phục diện mạo thật, khiến mọi người xác nhận hắn chính là Hoang. Hắn cùng Yêu Nguyệt Công Chúa trêu chọc việc đổi Vương Hi lấy cổ thiên công, Thập Hung Bảo Thuật hoặc Bình Loạn Quyết, làm nàng vô cùng phẫn nộ. Tứ trưởng lão xuất hiện, yêu cầu các học sinh chỉ được luận bàn và buộc Thạch Hạo thả Vương Hi. Sau đó, Thạch Hạo cùng Mạc Đạo tiến vào thạch lô, nơi tro dược cổ vẫn còn lưu lại tiên khí và nhiều cơ duyên. Hắn thu được một lượng thần dịch chưa khô cạn rồi dùng Võ đạo Thiên nhãn tìm thấy mảnh đan lớn như răng rồng, nghi là tàn phiến Cửu Chuyển Tiên Đan."},{"chuong":1165,"tieuDe":"Cổ Đan","tomTat":"Thạch Hạo tìm được một mảnh đan ám kim còn linh tính trong tro tàn, được Mạc Đạo xác định là đan xen lẫn sinh ra khi luyện vô thượng tiên đan và vẫn có khả năng phạt mao tẩy tủy. Mọi người khám phá thạch lô rộng khoảng tám trăm dặm, nhận ra lần luyện đan cuối cùng thời cổ đã thất bại và làm hỏng cả đan lẫn lò. Tại nơi dược tính tập trung, họ phát hiện mười mảnh cổ đan trắng còn khả năng cải thiện thể chất, thậm chí giúp người dùng Niết Bàn trùng sinh. Thạch Hạo, Mạc Đạo, Lục Đà, Vương Hi, Thập Quan Vương, Huyền Côn và Yêu Nguyệt Công Chúa lao vào hỗn chiến, khiến khu vực trở thành chiến trường chỉ dành cho các Chí Tôn trẻ tuổi. Thạch Hạo lần lượt dùng pháp môn Côn Bằng và Bảo thuật Liễu Thần đối đầu nhiều cường giả, đồng thời phản kích Vương Hi sau khi bị Hoàng Kim bảo ấn đánh trúng. Cuối trận, tất cả đều mang thương tích, còn Thạch Hạo giành được ba mảnh cổ đan trắng. Hắn dùng một mảnh hòa vào thần tuyền, phối hợp với đạo pháp trên Bạch Ngọc Sơn để bài xuất tạp chất và hoàn thành lần lột xác đầu tiên bằng Tiên Cổ pháp."},{"chuong":1166,"tieuDe":"Tấn Cấp Thiên Thần","tomTat":"Sau khi được Tứ trưởng lão giải đáp, Thạch Hạo hòa tan những mảnh tiên đan còn lại trong thần tuyền rồi ngâm mình hấp thu dược lực, tránh nguy cơ đan độc do trực tiếp nuốt cổ đan. Quá trình luyện hóa giúp hắn tiếp tục rèn thân và nhận ra Tiên cổ pháp với đương đại pháp mở bảo tàng thân thể theo những phương thức khác nhau. Hắn dùng phần dược lực còn lại cùng phối dược màu vàng sậm để bồi dưỡng đạo tiên khí thứ ba, khiến tiên khí liên tục ngưng tụ và biến hóa. Dị tượng ngân hà, kim liên, Chân Long và phượng hoàng xuất hiện quanh vùng bế quan, thu hút sự chú ý của Vương Hi, Lục Đà, Thập Quan Vương và Yêu Nguyệt Công Chúa. Đạo tiên khí thứ ba cuối cùng kết thành đại đạo chi hoa, hoàn thiện trạng thái ba đóa hoa khi Thạch Hạo vẫn còn ở Thánh Tế cảnh. Thành tựu ấy khiến hắn lập tức tấn cấp Thiên Thần khi chưa đủ hai mươi tuổi, buộc các thiên tài cùng thế hệ phải đánh giá lại sức mạnh và vị thế của Hoang."},{"chuong":1167,"tieuDe":"Không Linh","tomTat":"Thạch Hạo chính thức tiến vào Thiên Thần cảnh, bài xuất tạp chất và cốt chất vụn, khiến thân thể, thần giác, tốc độ cùng cường độ công kích đều được nâng cao. Ba đạo tiên khí đã hòa vào thân thể và có thể biến hóa theo ý niệm, nhưng hắn chưa thể độ kiếp vì phải tìm một tiên chủng phù hợp rồi mới dùng lôi đình hoàn thành quá trình dung hợp. Trong lúc chờ trưởng lão Thiên Thần thư viện dẫn đội tới Giới phần, hắn trở lại Bạch Ngọc sơn lĩnh hội trăm vạn phù văn và nhận thấy hiệu suất tăng rõ rệt. Chiến tích giành ba mảnh tiên đan và từng bắt giữ Vương Hi khiến những người tu cổ pháp xung quanh kính sợ, không còn dám tùy tiện khiêu khích. Yêu Nguyệt Công Chúa tiếp tục mời hắn tới nhà và đem Vương Hi ra làm lễ vật để châm chọc Vương gia. Thanh Y vừa xuất quan đã tới gặp nhưng tránh khi hắn định nắm tay, còn Nguyệt Thiền lập tức mất vui sau lời chào suồng sã của hắn trước mặt mọi người."},{"chuong":1168,"tieuDe":"Xuất Quan","tomTat":"Thạch Hạo xuất quan và gặp lại Nguyệt Thiền, nhưng lời khiêu chiến của hắn bị nàng từ chối vì nàng biết mình chưa thể đối địch nếu không dung hợp với Thanh Y. Hắn tiếp tục hẹn chiến với Lục Đà, đề nghị Vương Hi trao đổi Bình Loạn Quyết nhưng không thành, qua đó nhắc lại nguồn gốc và chiến tích hiển hách của kiếm quyết này trong cuộc chiến với dị vực. Thập Quan Vương cũng chủ động khiêu chiến Thạch Hạo, song Tứ trưởng lão ngăn hai người giao đấu để họ giữ sức đối kháng Thánh Viện và Tiên Viện. Trong cuộc đối thoại, Thập Quan Vương công khai tên thật Thiên Tử và để lộ lai lịch đến từ chín tầng trời. Thạch Hạo cùng Thanh Y sau đó giao cảm thần niệm, mất ba tháng giải mã hoàn chỉnh trăm vạn văn tự cổ và được phép rời phế tích. Tứ trưởng lão yêu cầu họ ở lại thư viện chờ nghe giảng Tiên cổ chân kinh, còn Thanh Y đề nghị đi thăm những bằng hữu hạ giới đang sống tại các khu vực khác. Thạch Hạo đồng ý vì cũng muốn biết tình hình của Ma nữ và em trai Tần Hạo."},{"chuong":1169,"tieuDe":"Kiếp Này Pháp Cao Thủ","tomTat":"Sau khi học viên Thiên Thần Thư Viện chia theo cổ pháp và pháp đương thời, sự cạnh tranh giữa hai con đường tu hành ngày càng gay gắt. Vương Dương phô diễn thành quả luyện thân bằng khí huyết đủ sức nung đá thành dung nham, còn Lam Mông tiết lộ mình đã đột phá mới ở Động Thiên và Hóa Linh. Hai người bàn về thành tựu của Tào Vũ Sinh và việc tu sĩ ba nghìn đạo châu đang bị nhằm vào, nhưng vẫn tưởng Hoang đã chết. Ở một vùng núi khác, Nguyên Đằng dùng minh văn ảnh hưởng thời không và quyết định đánh tan hai đạo tiên khí để nuôi dưỡng thân thể cùng Nguyên Thần. Kim Vân thừa nhận đã đánh Phượng Vũ bị thương rồi đoạt mũi tên đúc từ bảy màu tiên kim, đồng thời tỏ thái độ khinh thị người hạ giới. Đúng lúc nàng rủ Nguyên Đằng ra ngoài tham gia tranh đấu, Thạch Hạo và Thanh Y xuất hiện bên ngoài khu vực tu luyện."},{"chuong":1170,"tieuDe":"Tìm Cố Nhân","tomTat":"Thạch Hạo cùng Thanh Y tới khu vực tu luyện pháp đương đại để tìm những cố nhân đang phân tán, đồng thời bày tỏ ý định nghiên cứu cả cổ pháp lẫn pháp đương đại và tương lai khai sáng con đường riêng. Trưởng lão giữ sơn môn ban đầu không cho họ vào, nhưng đổi ý khi Thạch Hạo triển khai duy nhất động thiên và chứng minh thành tựu cực điểm trong Động Thiên cảnh. Hai người sau đó biết Phượng Vũ đã bị Kim Vân đánh trọng thương và cướp bảy màu tiên kim tiễn. Khi tìm thấy Phượng Vũ trong nhà tranh giữa rừng tùng, họ thấy nàng vẫn khí huyết khô bại và nguyên khí tổn hại nặng nề, nên Thạch Hạo trao một giọt Hoàng Huyết giúp nàng chữa trị. Kim Vân dẫn Nguyên Đằng cùng một nhóm người tới, công khai ngăn cản bất kỳ ai cứu Phượng Vũ. Một nữ tử đi cùng Kim Vân lên tiếng khinh miệt, nhưng bị tiếng quát của Thạch Hạo chấn đến hộc máu và bay về phía vách đá, mở màn cuộc đối đầu."},{"chuong":1171,"tieuDe":"Đạo Thương","tomTat":"Thạch Hạo tiếp tục dùng sóng âm trấn áp nữ tử đi cùng Kim Vân, phá bí pháp phòng ngự và đánh nàng gãy nhiều xương. Phượng Vũ kể lại việc Kim Vân từng phá bỏ giao ước chỉ dùng pháp đương thời, vận dụng hai đạo tiên khí đánh lén, làm nhục nàng rồi cướp Thất Thải Tiên Kim tiễn. Thạch Hạo cho Phượng Vũ uống một giọt Hoàng Huyết và dùng Bảo thuật Lôi Đế thúc đẩy sức mạnh niết bàn, chữa cả thương tích thân thể lẫn đạo thương. Theo truyền âm của Kim Vân, Kỳ Hồng dùng sư tử hống phá nát nhà tranh nhằm quấy nhiễu quá trình chữa trị, nhưng Thạch Hạo dựng màn sáng bảo vệ Phượng Vũ và Thanh Y. Kỳ Hồng hiện nguyên hình lam sư tử và thi triển sư mao châm, song các đòn công kích đều bị lôi đình phá hủy. Thạch Hạo ngưng tụ trường đao lôi đình chém rơi nửa thân sau của Kỳ Hồng. Sau khi xác nhận Phượng Vũ đã khỏi đạo thương và chỉ cần tĩnh dưỡng thêm vài ngày, hắn quay sang gọi Kim Vân tới thanh toán ân oán."},{"chuong":1172,"tieuDe":"Múa Rìu Qua Mắt Thợ","tomTat":"Thạch Hạo yêu cầu Kim Vân trả lại Thất Thải Tiên Kim tiễn cho Phượng Vũ, nhưng nàng khẳng định đó là chiến lợi phẩm và phủ nhận việc từng hứa chỉ dùng kiếp này pháp. Kim Vân dùng Phúc Thiên Ấn hàng nhái trấn áp, song Thạch Hạo dùng thần liên trật tự trói bảo vật, ép nó thu nhỏ rồi luyện hóa và nuốt vào cơ thể. Khi nàng tiếp tục miệt thị Ba ngàn đạo châu, Thạch Hạo công khai mình cũng đến từ nơi đó và quyết định tiếp tục giao chiến. Bảo thuật Thao Thiết, các đòn đánh từ xa và nhiều bí bảo của Kim Vân đều bị hắn phá giải, khiến nàng bị thương. Kim Vân bí mật hóa hai đạo tiên khí thành tiên nhận để tập kích, nhưng Thạch Hạo bắt lấy bằng một tay và để lộ ba đạo tiên khí trong lòng bàn tay. Cuối cùng, hắn bóp cổ bắt giữ Kim Vân, khiến sự kiêu ngạo cùng mọi ưu thế mà nàng dựa vào hoàn toàn sụp đổ."},{"chuong":1173,"tieuDe":"Xấu Hổ","tomTat":"Kim Vân kinh hãi khi nhận ra Thạch Hạo có ba đạo tiên khí, nhưng vẫn bị hắn vượt qua thế công, bóp cổ và nhấc lên trước đông đảo người chứng kiến. Vì không nhìn thấy tiên khí của Thạch Hạo, những tu sĩ xung quanh lầm tưởng hắn đã tiến rất xa trên con đường kiếp này pháp và xem chiến thắng này là bằng chứng có thể đối kháng cổ pháp. Thạch Hạo ném Kim Vân xuống đất rồi công khai đánh nàng để đòi lại công bằng cho Phượng Vũ, đồng thời bác bỏ lời đe dọa dựa vào Kim gia trên chín tầng trời. Kim Vân giả vờ nổi giận nhằm che giấu đòn đánh lén bằng Thất Thải Tiên Kim tiễn từng cướp của Phượng Vũ, nhưng Thạch Hạo tạo tàn ảnh né tránh rồi áp sát đánh gãy nhiều xương của nàng. Khi Kim Vân ngã dưới chân Phượng Vũ, nàng bị đối phương chế nhạo đến thổ huyết. Theo lời Thạch Hạo, Phượng Vũ trực tiếp giẫm xuống để trả lại món nợ bị làm nhục trước đây."},{"chuong":1174,"tieuDe":"Ta Là Hoang","tomTat":"Sức mạnh Thạch Hạo để lại trong cơ thể Kim Vân tiếp tục gây đạo thương, buộc nàng phải cúi đầu xin lỗi, nhưng Phượng Vũ vẫn giẫm đạp đối phương đến mức trọng thương và gần mất mạng. Ở một vùng núi khác, Vương Dương và Lam Mông trao đổi về Kiếp này pháp, Tào Vũ Sinh cùng Hoang rồi chạy tới nơi Thất Thải Tiên Kim tiễn vừa xuất hiện. Nguyên Đằng chủ động trả mũi tên cho phía Phượng Vũ và chân thành xin Thạch Hạo tha Kim Vân, nên Thạch Hạo chấp thuận dù vẫn đá nàng văng vào núi đá. Nguyên Đằng sau đó đề nghị luận bàn, nhưng khi thấy Thạch Hạo có ba đạo tiên khí, hắn hiểu mình không thể thắng và quyết đoán chấn tan hai đạo tiên khí để chuyển sang chuyên tu Kiếp này pháp. Thạch Hạo đáp lại bằng Duy nhất động thiên được dung hợp từ mười động thiên, khiến Nguyên Đằng nhận ra vô thượng đạo quả của con đường này. Trước câu hỏi về danh tính, Thạch Hạo công khai mình chính là Hoang, làm đám đông chấn động vì người từng bị cho là đã chết vẫn còn sống."},{"chuong":1175,"tieuDe":"Mơ Ước","tomTat":"Tin Hoang vẫn còn sống làm cả vùng núi chấn động, còn thành tựu ba đạo tiên khí và duy nhất động thiên khiến Thạch Hạo được nhìn nhận như người mở đường cho kiếp này pháp. Nguyên Đằng từ bỏ ý định khiêu chiến, xin đi theo học hỏi nhưng được Thạch Hạo khuyên tiếp tục tới Thánh viện và chỉ hứa trao đổi nghi vấn trong thời gian gần. Thạch Hạo tha Kim Vân, yêu cầu Nguyên Đằng đưa nàng rời đi, trong khi nàng kinh hãi vì biết người đánh bại mình chính là Hoang. Vương Dương và Lam Mông vừa xuất quan liền chú ý tới Thất Thải Tiên Kim tiễn, nhưng Thạch Hạo tuyên bố món binh khí thuộc về Phượng Vũ và phải được trả lại chủ cũ. Lam Mông vẫn viện cớ bảo vệ bí bảo của Cửu Thiên để tranh đoạt, còn Kim Vân cố ý không cảnh báo thực lực của Thạch Hạo và hứa nhường tiên tiễn nếu hắn thắng. Thạch Hạo thách cả Lam Mông lẫn Vương Dương cùng ra tay, khiến Lam Mông lập tức tấn công trong khi Vương Dương vận chuyển khí huyết, chuẩn bị chặn đường lui."},{"chuong":1176,"tieuDe":"Sáng Tỏ","tomTat":"Lam Mông bất ngờ áp sát Thạch Hạo, thi triển Vàng ròng tay và tiêu hao Tiên Thiên tinh khí nhưng vẫn bị một chưởng đánh bay vào núi. Sau khi tái tạo huyết nhục, hắn kết hợp Động Thiên với Hóa Linh, cho mười thần thai phá kén và dùng tiên khí hiến tế, song Thạch Hạo gọi ra ba đóa đại đạo chi hoa quét gãy toàn bộ thần thai, khiến ba động thiên của hắn vỡ nát. Kim Vân chế giễu Lam Mông không lấy nổi tiên kim tiễn và bác bỏ lời cáo buộc rằng nàng đã cố tình che giấu thực lực của đối thủ. Vương Dương thừa nhận mình không địch nổi nhưng vẫn xin giao chiến nếu Thạch Hạo không dùng tiên khí; dù điều kiện được chấp thuận, mọi công kích của hắn đều không thể xuyên qua duy nhất động thiên và còn bị phản chấn trọng thương. Từ ba đóa đại đạo chi hoa, duy nhất động thiên cùng chuyện sống sót khỏi Thái Sơ cổ quáng, Lam Mông và Vương Dương nhận ra người trước mặt chính là Hoang. Thạch Hạo xác nhận mình từng xuất hiện tại tiên gia chiến trường và ở bên cạnh Vương Hi, khiến thân phận ẩn giấu của hắn hoàn toàn sáng tỏ. Đám đông cũng hiểu rằng người từng giết Tam Đầu Vương, chém Hư Không Thú và trở mặt với Vương gia chính là Hoang đã sớm tiến vào thư viện."},{"chuong":1177,"tieuDe":"Gặp Nhau","tomTat":"Thạch Hạo rời khỏi đám đông đang náo động vì sự trở lại của Hoang, rồi cùng Thanh Y và Phượng Vũ đi gặp những người quen tại Thiên Thần Thư Viện. Thái Âm Ngọc Thỏ mang Kỳ Lân trắng tới, trong khi Chân Cổ, Đằng Nhất, Tào Vũ Sinh và Trường Cung Diễn lần lượt xuất quan để dự cuộc hội ngộ. Bên lửa trại, mọi người nhắc lại sự chèn ép của tu sĩ Cửu Thiên nhưng cuối cùng đồng thuận không mở rộng xung đột khi nguy cơ dị vực tiến công đã cận kề. Thạch Hạo kể có chọn lọc chuyến đi Thái Sơ cổ quáng và xác nhận thu hoạch lớn nhất là truyền thừa Lục Đạo Luân Hồi. Cái chết của Nguyên Phong, Phong Hành Thiên và Phong Chiêu khiến hắn nhận ra Nguyên Thanh cùng Phong tộc có thể sớm trả thù. Khi trò chuyện với Kỳ Lân trắng, Thạch Hạo phát hiện nó còn nhớ Hoàng Nữ, một thiếu nữ từng ôm mình và thanh niên mang tiên kim kiếm. Hắn kết luận Kỳ Lân này không phải chuyển thế mà là sinh linh được phong ấn sống sót từ Tiên cổ, đồng thời quyết định tìm hiểu chuyện xưa qua những ký ức đang thức tỉnh của nó."},{"chuong":1178,"tieuDe":"Phiền Toái Hiện","tomTat":"Bạch Kỳ Lân ấu thú nhớ lại những nhân vật chí cao thời Tiên Cổ nhưng không biết nguyên nhân thực sự khiến dị vực rút lui sau đại chiến. Trong lúc luận đạo, Thạch Hạo biết Ninh Xuyên và Thạch Nghị đều chọn kiếp này pháp, đồng thời cân nhắc việc tới Thánh Viện hoặc Tiên Viện để học con đường phá vỡ cực hạn. Một trưởng lão tiết lộ Nguyên Thanh từng qua lại cả hai viện, có sư huynh quyền thế tại Thánh Viện, còn Phong Tộc cũng có người được bí mật thu nhận. Sau vài ngày củng cố trăm vạn phù văn để chuẩn bị vào Giới phần tìm tiên chủng, Thạch Hạo nhận tin người phía Nguyên Thanh tới hỏi về cái chết của Nguyên Phong. Hắn thẳng thừng từ chối gặp, bác bỏ danh xưng Chí Tôn của Nguyên Thanh và không chấp nhận yêu cầu nghênh tiếp. Khi người truyền lời tiếp tục thúc ép, Thạch Hạo đá văng hắn vào núi rồi công khai nhắc lại việc Nguyên Thanh từng cắt đứt con đường thành đạo và lưu đày mình tới Thái Sơ Cổ Quáng."},{"chuong":1179,"tieuDe":"Lộ Liễu Làm Càn","tomTat":"Thạch Hạo đánh bất tỉnh người truyền lời sau khi kẻ này tiếp tục dựa vào uy thế của Nguyên Thanh để đe dọa hắn. Nguyên Hồng, một cường giả cấp Giáo chủ thuộc dòng dõi Nguyên Thanh, đích thân đến Thiên Thần thư viện và thi triển Tụ lý càn khôn nhằm thu, luyện hóa Thạch Hạo. Thạch Hạo dùng Côn Bằng Sí thoát thân rồi dẫn đối phương đến ngọn núi nơi Ngũ trưởng lão đang tọa thiền; trưởng lão chỉ quát một tiếng đã phá tan thần thông của Nguyên Hồng. Hai bên tranh cãi về cái chết của Nguyên Phong và việc Nguyên Thanh từng hãm hại Thạch Hạo, nhưng Thạch Hạo từ chối yêu cầu dò xét thức hải. Theo đề nghị của hắn, Ngũ trưởng lão tạm ban pháp lực và đạo hạnh cấp Giáo chủ để hai người giao chiến cùng cấp. Thạch Hạo dùng Duy nhất động thiên hóa giải mười đạo thần quang, rồi liên tiếp vận Côn Bằng quyền đánh Nguyên Hồng hộc máu và gãy nhiều xương. Khi Nguyên Hồng cầu cứu, Ngũ trưởng lão công khai khiển trách ông ta và thể hiện rõ thái độ che chở Thạch Hạo."},{"chuong":1180,"tieuDe":"Ra Sức Đánh","tomTat":"Thạch Hạo dùng thực lực cấp giáo chủ cùng ba đạo Tiên khí áp đảo Nguyên Hoành, đánh đối phương gãy xương, rụng răng và mất hết khả năng chống trả. Khi hắn ngưng tụ kiếm quang định hạ sát đối phương, Ngũ trưởng lão kịp thời can thiệp và ra lệnh ném Nguyên Hoành khỏi Thiên Thần thư viện. Thạch Hạo dừng tay, kéo Nguyên Hoành ra ngoài rồi công khai trục xuất hắn trong tình trạng nhục nhã. Sau khi trị thương, Nguyên Hoành căm hận rời đi và quyết định tìm gặp sứ giả Thánh Viện sắp tới. Trong lúc đó, những người tu Kim Thế pháp và Cổ pháp lần lượt xuất quan để chuẩn bị tới các cổ địa, đặc biệt người học Cổ pháp phải tìm tiên chủng quyết định thành tựu tương lai. Bên hồ trong thư viện, Bạch Kỳ Lân ấu thú kể cho Thạch Hạo và các cố nhân về Giới phần, vùng đất cổ chứa tàn tích thế giới, tiên cốt và những hiểm họa từng khiến tuyệt đại cao thủ mất tích. Nơi này đồng thời có khả năng xuất hiện hoàn mỹ vũ trụ hạt giống, còn Thế Giới Thụ được truyền là từng được mang ra từ đó."},{"chuong":1181,"tieuDe":"Có?","tomTat":"Trong đêm trăng, nhóm thiên tài bàn về những con đường tu hành sắp tới: người tu Cổ pháp phải tìm tiên chủng hoàn mỹ, còn nhóm tu Kiếp này pháp sẽ tới Tổ huyệt tìm cơ hội đại niết bàn. Tổ huyệt được đồn từng thai nghén một sinh linh Tiên Đạo vừa xuất thế đã thành tiên, nhưng chỉ người hữu duyên mới có thể nhận được tạo hóa cải biến thân thể và Nguyên Thần. Ma nữ đến yến tiệc, khơi lại mối đối địch với Thanh Y và trêu chọc quan hệ giữa nàng với Thạch Hạo. Câu hỏi Thanh Y đã bí mật sinh con hay chưa khiến mọi người náo loạn, còn Tần Hạo và Thạch Hạo đều tin lời đồn trong chốc lát. Thanh Y vì tức giận và xấu hổ đã đánh Thạch Hạo, sau đó thách đấu Ma nữ vì cho rằng danh dự của mình bị bôi nhọ. Hai nữ nhân giao chiến dưới trăng trong khi mọi người hào hứng quan sát, còn Thạch Hạo kết thúc màn náo nhiệt bằng cách vỗ đầu Tần Hạo vì em trai vẫn chưa hiểu chuyện."},{"chuong":1182,"tieuDe":"Dị Vực Khách Đến Thăm","tomTat":"Giữa đêm, Thiết Huyết cổ thụ hiện lên trên Thiên Thần Thư Viện và cảnh báo ngoại địch xâm lấn, khiến toàn bộ tu sĩ cùng các trưởng lão lập tức đề phòng. Từ phía tây, khí tức đầy áp bức kéo tới và hư ảnh Hoàng Kim Tam Đầu Vương hiện ra trong khói đen, truy hỏi kẻ đã giết hậu nhân của mình. Các trưởng lão nhận ra chân thân của hắn chưa vượt giới mà chỉ được một tế đàn do sinh linh dị vực để lại từ kỷ nguyên Tiên Cổ chiếu sang. Tế đàn sau đó phát ra vô số ký hiệu, cưỡng ép ngưng tụ thành cánh cửa nối liền cửu thiên thập địa với dị vực. Qua cánh cửa ấy, một sứ giả hình người mặc chiến y Hắc Ám Tiên Kim dùng chân thân bước sang, dò xét quy tắc thiên địa và chịu lực bài xích của thế giới. Được chiến y bảo vệ, sứ giả rời tế đàn và tiến về Thiên Thần Thư Viện, báo hiệu nguy cơ đại chiến toàn diện giữa hai giới đang đến gần."},{"chuong":1183,"tieuDe":"Hoàng Kim Huyết","tomTat":"Một sứ giả mặc hắc ám tiên kim chiến y được Hoàng Kim Tam Đầu Vương hộ tống đến Thiên Thần Thư Viện và trao ngọc thạch thư khuyên mọi người quy hàng dị vực để đổi lấy Bất Hủ. Các trưởng lão kiên quyết bác bỏ, còn Nhị trưởng lão và Tào Vũ Sinh trấn an môn sinh rằng nếu dị vực thực sự đủ mạnh thì đã không cần phái người đến du thuyết. Hoàng Kim Tam Đầu Vương tuyên bố tổ tiên dị vực vẫn trường tồn, đề xuất kiến lập thần quốc Bất Hủ và phủ nhận những ghi chép về sự tàn ác của dị vực. Nhận ra sứ giả đang dùng giáp trụ dò xét quy tắc thiên địa, Ngũ trưởng lão ra tay định bắt giữ Nguyên Thần nhưng bị Tam Đầu Vương ngăn cản. Tam Đầu Vương sau đó đọc chú ngữ làm chiến y hé mở, khiến sứ giả bị thương và chảy ra dòng máu vàng thần thánh. Các trưởng lão nhận ra người này là hậu nhân của Người Bảo Vệ, huyết mạch từng chiến đấu đến gần như tuyệt diệt để bảo hộ thế giới. Đại trưởng lão khẳng định không thể để nhất mạch ấy tuyệt hậu, trong khi mọi người bắt đầu nghi ngờ mục đích thật sự của Tam Đầu Vương khi hắn thừa nhận dị vực đã nghiên cứu vô địch huyết thống từ lâu."},{"chuong":1184,"tieuDe":"Máu Đen","tomTat":"Tam Đầu Vương dùng sức mạnh cực hạn cùng lò nung hư không luyện hóa máu vàng của hậu nhân người bảo vệ, khiến phần lớn huyết dịch hóa tro nhưng một tia còn lại chuyển thành màu đen đầy lệ khí. Nó vin vào dị biến này để tuyên bố huyết mạch vàng chỉ là lớp che đậy cho một bản chất nguy hiểm, song các trưởng lão Thiên Thần Thư Viện cho rằng đối phương đã dùng thủ đoạn và cố ý ly gián. Tam Đầu Vương còn tiết lộ dị vực từng đào được táng thổ trong Thái Sơ cổ quáng và nhìn thấy máu đen chảy ra từ nơi sâu nhất, khiến Thạch Hạo liên tưởng đến bí ẩn về việc quân dị vực từng thắng trận nhưng sau đó rút lui. Nó đe dọa dị vực sắp giáng lâm để san bằng cổ khoáng, tiên uyên cùng Thượng Thương nơi, đồng thời dụ người trong thư viện xây thần miếu thờ phụng các cường giả Bất Hủ. Nhiều trưởng lão hợp lực thúc giục Thập Giới Đồ và Cửu Hoàng lô công kích, làm bóng mờ Tam Đầu Vương biến mất và tế đàn xuyên giới vỡ vụn. Hậu nhân người bảo vệ bị bỏ lại như một lễ vật hoặc manh mối khả nghi, sau đó bị Tứ trưởng lão và Ngũ trưởng lão khống chế theo lệnh đưa về thư viện điều tra."},{"chuong":1185,"tieuDe":"Thủ Hộ Giả Nhất Mạch","tomTat":"Hai trưởng lão dùng đại pháp lực và thần liên trấn áp sinh linh đến từ dị vực rồi áp giải về Thiên Thần thư viện, khiến toàn viện chấn động. Thạch Hạo theo Mạc Đạo lên Thần sơn, nơi hơn mười trưởng lão tập trung thẩm vấn tù binh trong kiến trúc thanh đồng. Sau khi hắc ám tiên kim chiến y bị tháo xuống, người bị bắt tự xưng là Độc Cô Vân, một nam tử có dung mạo mỹ lệ và dòng máu vàng bùng cháy khi nổi giận. Mạc Đạo xác nhận chưa từng gặp hắn, còn các trưởng lão dùng thần châm lấy máu rồi vận dụng nhiều loại cổ pháp để xác minh huyết thống. Kết quả cho thấy Độc Cô Vân thật sự là hậu nhân Thủ Hộ giả, mang một trong tứ đại huyết thống mạnh nhất thời Tiên Cổ. Độc Cô Vân kể rằng ba vị tổ tiên của mình đã bị chính những người từng được họ bảo vệ phản bội hại chết, vì vậy hắn trở về để báo thù. Các trưởng lão muốn cảm hóa hắn chiến đấu cho Cửu Thiên Thập Địa và dự phòng dùng cổ kinh độ hóa, nhưng Độc Cô Vân công khai khinh thường kỳ tài nơi đây, cho rằng họ không thể chống nổi dòng máu vàng hay sánh với Hoàng tộc cổ xưa của dị vực."},{"chuong":1186,"tieuDe":"Quét Ngang","tomTat":"Sau nhiều lần khuyên can không thành, các trưởng lão cho Độc Cô Vân xuống núi vì phần lớn những gia tộc hắn muốn báo thù đã tiêu vong, dù họ vẫn chưa giải thích được hiện tượng huyết dịch của hắn chuyển sang màu đen. Dưới chân thần sơn, Độc Cô Vân công khai chê học sinh Thiên Thần thư viện yếu kém, dùng một chưởng đánh bị thương hơn mười người rồi phá tan đội hình hợp kích vây bắt. Thạch Hạo xuống núi nhưng không muốn trực tiếp giao chiến với hậu nhân Thủ Hộ Giả, vì vậy phái Mạc Đạo ra thử sức. Cuộc đối đầu tạm ngừng khi Độc Cô Vân tiết lộ tỷ tỷ Mạc Đạo đã được Bất Hủ Giả tiếp dẫn và đang tu hành cùng người của một Hoàng tộc cổ xưa tại dị vực. Khi Lục Đà, Vương Hi, Huyền Côn và các kỳ tài khác tới nơi, Độc Cô Vân chọn Huyền Côn làm đối thủ. Bằng kim sắc huyết khí và pháp ấn cương mãnh, hắn áp đảo Huyền Côn, đánh đối phương trọng thương và tiếp tục phô bày uy thế của dòng dõi Thủ Hộ Giả."},{"chuong":1187,"tieuDe":"Thánh Sứ","tomTat":"Huyền Côn vận dụng ba đạo tiên khí nhưng vẫn bị Độc Cô Vân đánh trọng thương, khiến các cao thủ còn lại trong Thiên Thần Thư Viện không ai dám tiếp chiến. Đúng lúc đó, một sứ giả trẻ tuổi của Thánh Viện mang theo đồng thau thiên mâu xuất hiện tại sơn môn và ngạo mạn hỏi tìm Thạch Hạo. Nguyên Hồng đi cùng vị sứ giả, dựa vào thân phận bồi đồng để trở lại thư viện và lớn tiếng khiêu khích Thạch Hạo, nhưng bị Tào Vũ Sinh cùng những người trong bóng tối chế giễu. Khi Thánh Viện sứ giả xông tới, hắn bị Độc Cô Vân đánh ho ra máu rồi trúng Luân Hồi thần thông của Thạch Hạo, lập tức trở nên già yếu và suy nhược. Hai cường giả liên tiếp quật vị sứ giả qua lại đến mức hắn thất khiếu chảy máu và hôn mê. Sau đó, Thạch Hạo trực tiếp đối chưởng với Độc Cô Vân, được đối phương thừa nhận là rất mạnh và tuyên bố sẵn sàng trấn áp toàn bộ thành viên Hoàng tộc dị vực được đưa tới."},{"chuong":1188,"tieuDe":"Chổ Cấn Đến Giới Phần","tomTat":"Thạch Hạo và Độc Cô Vân ác chiến tại chiến trường cổ của Thiên Thần Thư Viện, một nơi chứa những thiên thạch từng bị cao thủ cổ đại luyện hóa. Độc Cô Vân dùng huyết khí vàng thúc đẩy các tảng đá trấn áp đối thủ, nhưng Thạch Hạo dùng quyền phá tan tất cả, khiến hắn dừng chiến và công nhận Thạch Hạo đủ tư cách đối đầu Hoàng tộc dị vực. Sau đó, Ngũ Trường Lão trừng phạt Nguyên Hồng vì dám trở lại thư viện, còn Thạch Hạo nhân lúc mang người ra ngoài đã lấy sạch pháp khí, đan dược và vật quý của đối phương. Độc Cô Vân tiếp tục được hộ tống vào Thái Sơ cổ quáng, khiến dòng máu đen bí ẩn tuôn ra trước khi hắn trở lại với sắc mặt tái xanh. Nhị Trưởng Lão sau đó dẫn Thạch Hạo, Độc Cô Vân cùng nhiều kỳ tài lên chiến hạm bạc, vượt qua tế đàn để tới Giới Phần tìm tiên chủng. Trên đường đi, Độc Cô Vân tiết lộ rằng tổ tiên mình từng đưa các thành viên Hoàng tộc từ thượng kỷ nguyên vào Giới Phần và tin rằng họ cùng hậu duệ vẫn còn sống. Giới Phần là thế giới phần mộ chứa nhiều vũ trụ cổ tàn tạ, từng xuất hiện Thế Giới Thụ và những hạt giống vũ trụ có thể giúp người tu hành thành tựu đại đạo viên mãn."},{"chuong":1189,"tieuDe":"Không Trọn Vẹn Vũ Trụ Chủng","tomTat":"Chiến hạm màu bạc đưa các trưởng lão và học sinh vượt qua hành trình hư vô dài bất thường, đến mức thân tàu được phù văn bảo vệ vẫn in dấu thời gian và ăn mòn. Tại biên giới Giới Phần, đoàn người gặp một dòng cát trắng khiến Nhị Trưởng Lão lập tức ra lệnh rút lui; khi tản ra, từng hạt cát nặng hơn đại tinh và bắn nổ hàng loạt ngôi sao. Nhị Trưởng Lão xác định đây là hạt giống vũ trụ không trọn vẹn, tuy có thể diễn hóa thiên địa nhưng đã mất khả năng trưởng thành ổn định và có thể sụp đổ bất cứ lúc nào. Vũ trụ chủng này từng bị một cường giả hàng phục để phong ấn nhân vật khó lường, khiến huyết nhục bị nghiền cùng cát và làm bảo vật nhiễm ma tính, có nguy cơ phản phệ chủ nhân. Sau khi vượt qua sương mù hỗn độn, chiến hạm chính thức tiến vào phần mộ thế giới và bắt gặp một cổ thụ khô héo khổng lồ mang vô số đại tinh như quả. Các trưởng lão phủ nhận đó là Thế Giới Thụ, rồi đoàn người tiếp tục phát hiện một thực vật xanh biếc đang dùng những phiến lá từng bước nuốt chửng các ngôi sao."},{"chuong":1190,"tieuDe":"Giới Phần","tomTat":"Chiến hạm màu bạc tiếp tục đi sâu vào Giới Phần và gặp Thực Tinh Thảo đang nuốt những tinh cầu tàn tạ, buộc đoàn người phải tránh đường. Các trưởng lão giải thích về những thế giới không trọn vẹn được mở trong hỗn độn, đồng thời khẳng định lai lịch thật sự của Giới Phần vẫn là bí ẩn mà cả nhân vật Tiên Đạo thời xưa chưa giải đáp được. Đoàn thám hiểm nhìn thấy một đoạn cành Thế Giới Thụ từng bị bồi dưỡng thành Ma Thụ nhưng đã khô héo, cùng thi hài của một Tiên Thiên thần linh khổng lồ đã bị lấy sạch huyết nhục và tinh hoa. Sau đó, khói xám của chiến linh xuất hiện và một chiếc huyết sắc cổ thuyền trôi ra từ phế tích tinh cầu. Con thuyền khóa chặt chiến hạm, tỏa sương xám ăn mòn thần lực và khiến các trưởng lão xác định rằng không thể đơn giản chạy trốn. Tiếng gào từ cổ thuyền đánh thẳng vào linh hồn các học sinh, biến hành trình thám hiểm thành một thử thách có nguy cơ tử vong. Cuối chương, nhiều bóng người hiện lên trên huyết sắc cổ thuyền rồi lao ra tấn công đoàn người."},{"chuong":1191,"tieuDe":"Chiến Linh","tomTat":"Huyết sắc cổ thuyền xuất hiện giữa khu cổ địa đầy sao và đại lục vỡ nát, phóng nhiều chiến linh phủ khói xám tập kích Chiến hạm màu bạc. Chúng nuốt và luyện hóa thần lực để xuyên qua màn sáng phòng hộ, trong khi các thống lĩnh cấp cao buộc những trưởng lão của Thiên Thần Thư Viện lần lượt rời chiến hạm nghênh chiến. Nhị Trưởng Lão cho biết chiến linh là tàn niệm của cường giả chết trận, được năm tháng nuôi dưỡng thành ý thức mới và dùng thần thức tạo nên thể phách. Khi số lượng lớn chiến linh tràn lên boong, chúng trực tiếp công kích Nguyên Thần rồi sát thương thân thể, khiến nhiều học sinh trọng thương hoặc tử trận. Thạch Hạo đánh giết chiến linh đầu tiên và xác nhận chúng tan thành lực lượng tinh thần thay vì để lại thi thể. Sau khi tiêu diệt Thần Điểu chín đầu, hắn phát hiện tinh khí của chiến linh có thể bồi bổ Nguyên Thần. Nhờ Duy nhất động thiên ngăn cản công kích tinh thần, Thạch Hạo chủ động xông vào giữa bầy chiến linh săn giết, khiến những người đang chịu tổn thất nặng phải kinh ngạc."},{"chuong":1192,"tieuDe":"Hồn Lực Hạt Giống","tomTat":"Nhận ra tinh khí của chiến linh có thể bồi bổ Nguyên Thần, Thạch Hạo chủ động săn giết đoàn chiến linh trên chiến hạm màu bạc, lần lượt tiêu diệt hình người Thiên Hạt và quái xà màu xám. Công kích linh hồn của chiến linh khiến nhiều học sinh Thiên Thần Thư Viện bị thương hoặc tử trận, nhưng Lục Đà, Vương Hi, Thập Quan Vương, Yêu Nguyệt, Huyền Côn và Độc Cô Vân sau đó cùng phản công, đảo ngược thế trận. Trong lúc giao chiến, các trưởng lão giải thích rằng chiến linh là tàn niệm của những nhân vật tuyệt thế đã chết nhưng vẫn tiếp tục trưởng thành và tiến hóa. Nhóm trưởng lão đánh bại phần lớn chiến linh cấp cổ tổ, rồi Nhị Trưởng Lão bổ vỡ huyết sắc cổ thuyền, khiến một hồn lực hạt giống vô giá xuất hiện. Chiến linh và học sinh lập tức lao vào tranh đoạt, còn Thạch Hạo phải giao thủ với Vương Hi, Lục Đà và Thập Quan Vương để tiếp cận mục tiêu. Cuối cùng hắn dùng duy nhất động thiên cầm cố hạt giống và kéo nó vào bên trong. Nhị Trưởng Lão liền tuyên bố kết thúc cuộc tranh đoạt để ngăn các học sinh tiếp tục tương tàn."},{"chuong":1193,"tieuDe":"Đạo Chủng","tomTat":"Sau khi huyết sắc cổ thuyền tan vỡ, Thạch Hạo thu được một viên hồn lực hạt giống có thể tẩm bổ Nguyên Thần và dùng để tu luyện Tiên cổ pháp. Người do Phong tộc sai đến đề nghị dùng cổ thiên công trao đổi, nhưng Thạch Hạo thẳng thừng từ chối và dùng sát khí ép hắn rút lui. Nhị Trưởng Lão khuyên Thạch Hạo rằng tu cổ pháp phải chuyên nhất, khiến hắn quyết định giữ đạo chủng để tự dùng. Trên đường tiến sâu vào Giới Phần, đoàn phát hiện đầu lâu khổng lồ của đệ tam cổ tổ Hoàng Kim cự nhân và chạm trán hình chiếu một cường giả Hoàng tộc dị vực bị giam. Nhị Trưởng Lão dùng Cửu Hoàng lô đánh lui hình chiếu rồi dẫn đoàn tiếp tục vượt qua vùng không thời gian loạn lưu. Cuối cùng, mọi người nhìn thấy một cổ thụ vàng nghi là Thế Giới Thụ cùng thế giới thạch khổng lồ, còn Thạch Hạo trầm mặc vì cảm thấy cả hai đều quen thuộc."},{"chuong":1194,"tieuDe":"Chuẩn Thế Giới Thụ","tomTat":"Chiến hạm màu bạc bắt gặp một cổ thụ vàng khổng lồ giữa Giới Phần, nhưng những học sinh vội lao ra tranh cơ duyên đều bị sức mạnh của cây tiêu diệt. Các trưởng lão xác nhận đây là một Chuẩn Thế Giới Thụ đang hấp thu dấu ấn từ những Cổ giới tan vỡ để tiếp tục tiến hóa. Thạch Hạo nhận ra cổ thụ từng xuất hiện sau biến cố Bất Lão Sơn và gặp lại cô gái cánh vàng sống trên tán cây. Nhị trưởng lão quyết định cho chiến hạm mạo hiểm truy đuổi vì hành trình của cây có thể dẫn tới nhiều vùng tạo hóa chứa Đạo chủng quý. Đoàn người theo cổ thụ tới Ngũ hành đại lục, nơi năm loại bản nguyên cùng lưu chuyển và Chuẩn Thế Giới Thụ cắm rễ hấp thu Ngũ hành mẫu khí. Vừa rời chiến hạm, Huyền Côn đã dùng ba đạo tiên khí quấn giữ một viên hỏa đạo chủng trong hang cổ màu đỏ. Sau đó, các trưởng lão công bố lời đồn về Ngũ hành tiên chủng hoàn mỹ và thúc giục toàn bộ học sinh tranh lấy cơ duyên lớn nhất tại cổ địa."},{"chuong":1195,"tieuDe":"Không Tự Trọng","tomTat":"Nhị Trưởng Lão tiết lộ Ngũ hành đại lục có thể cất giấu một viên Ngũ hành tiên chủng chưa từng bị ai thu phục, khiến các đệ tử hào hứng tản ra tìm kiếm. Yêu Nguyệt phá mở một ngọn núi linh khí, lấy được Thủy đạo hạt giống xanh lam và khiến những người đến sau từ bỏ ý định tranh đoạt. Thạch Hạo kéo Thanh Y cùng đi tìm cơ duyên, còn Nguyệt Thiền bám theo vì không muốn hắn tiếp tục gần gũi thứ thân của mình. Lợi dụng sự giao cảm giữa chủ thân và thứ thân, Thạch Hạo cố ý thân mật với Thanh Y, khiến Nguyệt Thiền tức giận và phải bỏ đi. Sau đó hắn thuật lại lời Đại trưởng lão về nguy cơ các thiên tài chết trận trong tương lai và kế hoạch sớm lưu lại hậu duệ mang huyết mạch mạnh. Thạch Hạo cũng hứa sẽ giúp Thanh Y giữ quyền chủ đạo khi dung hợp với Nguyệt Thiền. Cùng lúc ấy, một chiến thuyền cổ bị tiên vụ và tiên khí che phủ âm thầm từ hư không Giới Phần tiến xuống Ngũ hành đại lục."},{"chuong":1196,"tieuDe":"Cổ Bi","tomTat":"Thạch Hạo và Thanh Y tiến vào vùng đất kim loại trên Ngũ hành đại lục, phát hiện một hồ chất lỏng nóng rực đang thai nghén đạo chủng thuộc tính Kim. Thạch Hạo dùng Côn Bằng pháp, kiếm khí và lôi điện tiêu diệt các sinh linh kim loại bảo vệ, sau đó bắt được đạo chủng đang hóa thành đỉnh nhỏ chạy trốn. Hắn tặng đạo chủng cho Thanh Y, nhưng vòng Thanh Nguyệt của nàng tự hiện ra, hấp thu toàn bộ tinh khí khiến đạo chủng vỡ thành phế kim và bắt đầu thai nghén sinh cơ. Kèn lệnh của Thiên Thần Thư Viện triệu tập mọi người tới một cổ bi Ngũ hành ghi manh mối Ngũ Ma Phong Thiên Chủng, khiến các trưởng lão quyết định tổ chức tìm kiếm thiên chủng tại những khu vực khả nghi. Đoàn người dùng tế đàn xương truyền tống chiến hạm màu bạc tới vùng núi lửa Ngũ hành, nơi Thạch Hạo mang Thanh Y tranh tới núi lửa trung tâm. Một cổ thuyền mang tiên khí bất ngờ từ vực ngoại trấn xuống miệng núi lửa, làm các trưởng lão biến sắc. Nhóm người trẻ tuổi trên thuyền xuất hiện, trong đó một người coi hình thái Côn Bằng của Thạch Hạo là con mồi và giương cung nhắm bắn hắn."},{"chuong":1197,"tieuDe":"Ngông Cuồng","tomTat":"Khi Thạch Hạo đang hóa thành Côn Bằng và mang theo Thanh Y, Ngô Thái từ một cổ thuyền bất ngờ dùng thanh đồng tiễn săn bắn hắn, phá hủy nhiều núi lửa kiên cố trên Ngũ hành đại lục. Thạch Hạo vận dụng cực tốc né tránh rồi phóng lông thần màu vàng phản kích, buộc đối phương dùng giáp trụ và chiến mâu chống đỡ. Sau khi hóa lại hình người và đưa Thanh Y đáp xuống miệng núi lửa, hắn chất vấn nhóm người trên thuyền nhưng chỉ nhận lại lời trách ngược và những câu trêu ghẹo nhắm vào Thanh Y. Thạch Hạo bắn trả cổ thuyền, song nhóm thanh niên Tiên viện cùng niệm chú kích hoạt màn sáng phòng hộ và thiêu mũi tên thành tro. Động tĩnh khiến các trưởng lão hai bên xuất hiện, qua đó xác nhận cổ thuyền thuộc Tiên viện, thánh địa chuyên tu cổ pháp. Trưởng lão Thiên Thần thư viện và Tiên viện xem vụ việc là hiểu lầm giữa người mình, nhưng nhóm thanh niên trên thuyền vẫn không hối lỗi. Trước lời mời gọi khinh bạc tiếp tục nhắm vào Thanh Y, Thạch Hạo công khai thách Ngô Thái xuống thuyền giao chiến."},{"chuong":1198,"tieuDe":"Trực Trữ Tâm Ý","tomTat":"Sau nhiều lần bị người của Tiên Viện gây khó dễ, Thạch Hạo quyết định không tiếp tục nhường nhịn và dùng chiến mâu lôi đình công kích cổ thuyền của họ. Ngô Thái rời thuyền nghênh chiến, lần lượt sử dụng mũi tên đồng thau bí chế và Thần niệm tỏa hồn tiễn để truy sát đối phương. Thạch Hạo hóa thành Côn Bằng, dựa vào tốc độ cực hạn áp sát rồi vận chuyển sức mạnh chí dương và chí âm để khống chế Ngô Thái. Hai cánh âm dương giao hội làm bùng phát Hỗn Độn quang, phá vỡ màn sáng do giáp trụ xanh thẳm dựng lên và đánh trường cung tuột khỏi tay Ngô Thái. Trong khi Vương Hi và Lục Đà đứng quan sát, Thanh Y lo ngại hậu quả của việc Thạch Hạo đắc tội Tiên Viện. Cuối cùng, Thạch Hạo hóa lại hình người, giẫm lên ngực Ngô Thái và đạp hắn chìm xuống dung nham trong miệng núi lửa."},{"chuong":1199,"tieuDe":"Đắc Chí Càn Rỡ","tomTat":"Thạch Hạo giẫm Ngô Thái chìm xuống dung nham, khiến đối thủ vừa chịu thương tổn do lực xoắn Thái Âm–Thái Dương vừa bị sỉ nhục. Nhờ giáp trụ xanh thẳm mượn từ tiểu Thiên Vương, Ngô Thái thoát ra, tăng mạnh chiến lực rồi dùng thiên mâu cùng ba đạo tiên khí biểu kiến phản kích. Sau khi quan sát đủ bí mật của bảo giáp, Thạch Hạo dung hợp lôi đình với pháp môn Côn Bằng, tay không bẻ gãy thiên mâu và liên tiếp trọng thương đối thủ. Hắn dùng lôi đình bắt Ngô Thái trở lại rồi triển khai Côn Bằng trảo cưỡng ép tháo giáp trụ. Mất bảo giáp, Ngô Thái chỉ còn hai đạo tiên khí, qua đó để lộ đạo thứ ba và phần chiến lực tăng thêm đều đến từ ngoại vật. Thạch Hạo cuối cùng vận dụng ba đạo tiên khí thật đánh nát nửa người Ngô Thái và tiếp tục giẫm xuống thân thể đã gần như tàn phế."},{"chuong":1200,"tieuDe":"Mãnh Nhân","tomTat":"Thạch Hạo giẫm nát thân thể Ngô Thái nhưng để lại đầu lâu, sau đó công khai thách đấu những đệ tử Tiên Viện bất mãn. Hai người dùng bí bảo xuống thuyền giao chiến đều bị kiếm khí của hắn phá hủy thân thể, khiến ba đệ tử Tiên Viện liên tiếp chỉ còn lại đầu lâu. Kiếm pháp Thạch Hạo thi triển bị nhận nhầm là Bình Loạn Quyết, song Vương Hi nhận ra hắn chỉ mô phỏng pháp quyết của nàng và sức mạnh thực sự đến từ bản thân hắn. Ba đệ tử còn lại không dám ứng chiến, trong khi nội bộ Tiên Viện cũng chỉ trích họ tự làm mất thể diện. Khi phía Tiên Viện yêu cầu trả giáp trụ của Tiểu Thiên Vương, Thạch Hạo khẳng định đó là chiến lợi phẩm đoạt từ Ngô Thái. Ngay cả lời gây sức ép của một lão quái vật cũng không khiến hắn nhượng bộ, bởi hắn muốn giữ món đồ cổ có thể tạo thêm một đạo tiên khí để nghiên cứu. Cuối chương, một nhóm nam nữ trẻ tuổi khí chất siêu phàm bước ra khỏi khoang thuyền và đồng thời nhìn về phía Thạch Hạo."}];
